df'),('20bed892-7869-5b65-800c-a8e45bd72309',1,'{\"report\": {\"id\": \"20bed892-7869-5b65-800c-a8e45bd72309\", \"createdAt\": \"2026-09-20T15:54:33\", \"metadata\": {\"title\": \"关于进一步扩大政府采购支持绿色建材\", \"documentNo\": \"\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"textHash\": \"9d6466d0e4d7e136060538607a618e646560381a5bb1edcb03bf079bbe1b6735\", \"decision\": \"PASS\", \"score\": 100, \"scores\": {\"ENCODING\": 100, \"AUTHENTICITY\": 100, \"FORMAT\": 100, \"QUALITY\": 100}, \"issues\": [], \"evidence\": {\"officialMetadata\": {\"title\": \"关于进一步扩大政府采购支持绿色建材\", \"documentNo\": \"\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"9d6466d0e4d7e136060538607a618e646560381a5bb1edcb03bf079bbe1b6735\", \"validitySourceUrl\": \"/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}, \"admitted\": true, \"chunkCount\": 1, \"workflowStatus\": \"APPROVED\", \"aiModel\": \"manual-import\", \"aiCompletedAt\": \"2026-09-20T15:54:33\", \"manualReviewerId\": 1, \"manualReviewedAt\": \"2026-09-20T15:54:33\", \"manualNote\": \"批量导入：已审核通过并发布到金融政策库。\"}, \"text\": \"扫描版政策PDF：关于进一步扩大政府采购支持绿色建材\\n原始文件：关于进一步扩大政府采购支持绿色建材.pdf\\n正文需要OCR校对后再用于精确问答。\", \"filename\": \"关于进一步扩大政府采购支持绿色建材.pdf\", \"parsingIssues\": [], \"submittedBy\": 1, \"evidenceHistory\": [{\"officialMetadata\": {\"title\": \"关于进一步扩大政府采购支持绿色建材\", \"documentNo\": \"\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"9d6466d0e4d7e136060538607a618e646560381a5bb1edcb03bf079bbe1b6735\", \"validitySourceUrl\": \"/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}], \"chunks\": [{\"ordinal\": 1, \"startOffset\": 0, \"endOffset\": 72, \"text\": \"扫描版政策PDF：关于进一步扩大政府采购支持绿色建材\\n原始文件：关于进一步扩大政府采购支持绿色建材.pdf\\n正文需要OCR校对后再用于精确问答。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}], \"chunking\": {\"category\": \"FINANCE_POLICY\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 800, \"overlap\": 80, \"delimiterRegex\": null}, \"pages\": []}',NULL,'PASS','2026-09-20 15:54:33','/files/finance-policy/关于进一步扩大政府采购支持绿色建材.pdf'),('20c08eb1-4de5-5df8-ba7e-34d0de5e01b2',1,'{\"report\": {\"id\": \"20c08eb1-4de5-5df8-ba7e-34d0de5e01b2\", \"createdAt\": \"2026-09-20T15:54:33\", \"metadata\": {\"title\": \"陕财办金〔2026〕23号 秦科贷风险补偿实施细则\", \"documentNo\": \"陕财办金〔2026〕23号\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"textHash\": \"cc150b8cb52b2efc431525db2f8a0d2d0cafbaee24d06b9a80bd4649f001f368\", \"decision\": \"PASS\", \"score\": 100, \"scores\": {\"ENCODING\": 100, \"AUTHENTICITY\": 100, \"FORMAT\": 100, \"QUALITY\": 100}, \"issues\": [], \"evidence\": {\"officialMetadata\": {\"title\": \"陕财办金〔2026〕23号 秦科贷风险补偿实施细则\", \"documentNo\": \"陕财办金〔2026〕23号\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"cc150b8cb52b2efc431525db2f8a0d2d0cafbaee24d06b9a80bd4649f001f368\", \"validitySourceUrl\": \"/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}, \"admitted\": true, \"chunkCount\": 8, \"workflowStatus\": \"APPROVED\", \"aiModel\": \"manual-import\", \"aiCompletedAt\": \"2026-09-20T15:54:33\", \"manualReviewerId\": 1, \"manualReviewedAt\": \"2026-09-20T15:54:33\", \"manualNote\": \"批量导入：已审核通过并发布到金融政策库。\"}, \"text\": \"— 第 1 页 — \\n陕西省财政厅 陕西省科学技术厅 中共陕西省委金融委员会办公室 \\n关于印发《陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则》的通知  \\n各设区市、杨凌示范区财政局、科技局，西安市委金融办、各设区市地方金融管理部\\n门、杨凌示范区地方金融监管局，有关金融机构： \\n为贯彻落实国家和省委、省政府关于做好科技金融首篇大文章的决策部署，引导\\n金融机构加大对科技企业的融资支持力度，促进科技、产业、金融实现深度融合与良\\n性循环，推动金融资源向科技创新领域集聚。 \\n经研究，决定在陕西省中小微企业贷款风险补偿资金项下设立陕西省中小微科技\\n企业银行贷款（秦科贷）风险补偿资金。 \\n为保障风险补偿工作安全、高效、规范运行，结合工作实际，特制定《陕西省中\\n小微科技企业银行贷款（秦科贷）风险补偿实施细则》。 \\n现予印发实施，请遵照执行。 \\n陕西省财政厅  陕西省科学技术厅  中共陕西省委金融委员会办公室 \\n2026 年 7 月 1 日 \\n  \\n— 第 2 页 — \\n陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则  \\n第一章  总  则 \\n第一条  为贯彻落实国家和省委、省政府关于做好科技金融首篇大文章的决策部\\n署，引导金融机构加大对科技企业的融资支持力度，促进科技、产业、金融实现深度\\n融合与良性循环，推动金融资源向科技创新领域集聚，按照《陕西省财政厅等七部门\\n关于修订印发〈陕西省中小微企业银行贷款风险补偿资金管理办法〉的通知》（陕财\\n办金〔2026〕9 号）工作要求，制定本细则。 \\n第二条  “秦科贷”是省科技厅会同省财政厅、省委金融办，在省中小微企业银行贷\\n款风险补偿资金（以下简称“省风险补偿资金”）项下设立的子项目，重点支持科技企\\n业通过信用、科技成果、人才、股权、无形资产等获得的贷款。 \\n第三条  “秦科贷”风险补偿资金适用企业名录：申报省级科技计划项目、提名省科\\n学技术奖的科技企业；创新积分制优质科技企业；与省科技厅建立合作关系的投资\\n（保险）机构已投（已保）科技企业。 \\n第二章  合作银行的确定 \\n第四条  省科技厅会同省财政厅、省委金融办发布“秦科贷”合作银行申报通知，符\\n合条件的银行业金融机构按要求提交书面申请。意向银行由其总行或省级分行（一级\\n分支机构）统一申报。 \\n第五条  省科技厅会同省财政厅、省委金融办按照本细则及申报通知要求开展评\\n审，择优确定合作银行，优先选择： \\n（一）纳入科技金融常态化推送机制的银行； \\n（二）服务中小微科技企业数量大、贷款多、利率低的银行； \\n（三）设立科技信贷产品、建立科技贷款绿色通道、风险防控体系健全、科技金\\n融服务能力突出的银行。 \\n第六条  省科技厅与合作银行、托管机构签订三方合作协议，原则上合作期限为 3\\n年。 \\n第七条  省科技厅会同省财政厅、省委金融办对合作银行实行年度考核评价，考核\\n不合格的，视情况暂停或取消合作资格，并可根据工作需要适时增补合作银行。 \\n— 第 3 页 — \\n第三章  管理职责与分工 \\n第八条  省财政厅负责筹措安排、审核拨付省风险补偿资金；参与合作银行遴选、\\n考核评价与绩效管理。 \\n第九条  省科技厅负责建立并动态管理“秦科贷”风险补偿资金适用企业名录；牵头\\n开展合作银行遴选；审核合作银行提交的风险补偿申请；组织实施合作银行考核评价\\n与绩效管理。 \\n第十条  省委金融办负责指导金融机构加大对“秦科贷”适用企业信贷投放，加强政\\n策宣传与银企融资对接；参与合作银行遴选、考核评价与绩效管理。 \\n第十一条  合作银行负责建立健全“秦科贷”工作机制，优化业务流程，提升放款效\\n率，做好企业融资服务；与“秦科贷”适用企业自主对接，独立审核、发放贷款；按季\\n度向托管机构报送贷款投放、不良贷款等数据；如实申报风险补偿，做好不良贷款追\\n偿、风险处置及追偿资金清算返还；配合相关部门开展数据核查、绩效评价与监督检\\n查。 \\n第十二条  托管机构负责按季度统计合作银行“秦科贷”业务开展情况，并报送省财\\n政厅、省科技厅、省委金融办；受理合作银行风险补偿申请并出具初审意见；按规定\\n及时拨付补偿资金；按年度向省财政厅报送资金运行报告；配合相关部门开展绩效评\\n价与监督检查。 \\n第四章  补偿条件与程序 \\n第十三条  贷款额度。省财政厅会同省科技厅根据省风险补偿资金规模、不良贷款\\n情况等，可对“秦科贷”采取设定年度投放额度上限、实施余额管控等措施。“秦科贷”\\n单户贷款额度最高 3000 万元。 \\n第十四条  贷款期限。根据企业生产经营周期合理确定，原则上不超过 3 年，中长\\n期项目可延长至 5 年。 \\n第十五条  贷款利率。原则上不超过同期贷款市场报价利率（LPR）+100BP。合\\n作银行不得另外收取贷款保证金、融资手续费等任何其他费用。 \\n第十六条  担保方式。单户贷款额度不超过 500 万元的，以信用方式投放，企业无\\n需提供抵押、质押等担保措施；对于单户贷款额度超过 500 万元的，可追加其他抵\\n— 第 4 页 — \\n押、质押措施。 \\n第十七条  补偿条件。“秦科贷”风险补偿对象为确定的合作银行，申请补偿须同时\\n满足以下条件： \\n（一）贷款对象应纳入“秦科贷”企业名录，且为签订合作协议后新发放贷款形成\\n的不良贷款； \\n（二）贷款符合本细则关于贷款额度、贷款期限、贷款利率等要求； \\n（三）贷款资金仅限用于企业和科技创新相关的日常生产经营活动，不得用于偿\\n还企业其他借款，不得用于金融投资、理财等套利活动，不得用于投资国家产业政策\\n禁止和限制的项目。 \\n第十八条  不良贷款认定与补偿标准。“秦科贷”贷款本金逾期满 90 天仍无法收\\n回，且合作银行已向人民法院提起诉讼并取得立案通知书；或贷款虽未逾期满 90 天但\\n已进入司法追偿程序的，认定为不良贷款，合作银行可启动风险补偿申请程序。对确\\n认的不良贷款本金余额，按以下比例给予风险补偿： \\n（一）“首贷”企业融资。单户贷款金额 500 万元（含）以内的，补偿比例为\\n70%；单户贷款金额 500 万元（不含）—1000 万元（含）的，补偿比例为 60%；单户\\n贷款金额 1000 万元（不含）—3000 万元（含）的，补偿比例为 50%。 \\n（二）非“首贷”企业融资。单户贷款金额不超过 1000 万元（含）的，补偿比例为\\n50%；单户贷款金额 1000 万元（不含）—3000 万元（含）的，补偿比例为 40%。 \\n风险补偿比例汇总表： \\n企业类型 贷款金额区间 风险补偿比例 \\n首贷企业 ≤500 万元（含） 70% \\n首贷企业 500 万元（不含）—1000 万元\\n（含） \\n60% \\n首贷企业 1000 万元（不含）—3000 万元\\n（含） \\n50% \\n非首贷企业 ≤1000 万元（含） 50% \\n非首贷企业 1000 万元（不含）—3000 万元\\n（含） \\n40% \\n— 第 5 页 — \\n第十九条  单户企业在“秦科贷”风险补偿资金下每次只能申请一笔贷款（同一借款\\n合同项下多笔支用、多张借据统一认定为单笔贷款，借据须与对应借款合同一一对\\n应，且限于同一自然年度），且不得在其他中小微企业银行贷款风险补偿资金子项目\\n下同时申请贷款；已享受过市（县）设立的风险补偿资金支持的贷款不得再申请“秦科\\n贷”政策支持。 \\n第二十条  补偿流程。 \\n（一）合作银行于每季度结束后 5 个工作日内向托管机构提交风险补偿申请材\\n料，包括风险补偿申请书，贷款合同、放款凭证等贷款发放证明材料，以及逾期证\\n明、不良认定、司法立案材料等其他必要材料； \\n（二）托管机构在 5 个工作日内完成合规性审核并出具审核意见； \\n（三）省科技厅在 5 个工作日内完成复审，必要时开展实地核查； \\n（四）省财政厅对符合补偿条件的，在复核结束后 5 个工作日内通知托管机构拨\\n付省风险补偿资金。 \\n第二十一条  追偿与资金返还。风险补偿资金拨付后，合作银行应继续采取有效措\\n施追偿不良贷款。合作银行追偿或处置所得资金，扣除合理费用后，须在资金到账之\\n日起 10 个工作日内，按原风险分担比例返还至省风险补偿资金池，并书面报告省财政\\n厅、省科技厅及托管机构。 \\n第二十二条  “秦科贷”业务整体贷款不良率原则上不超过 4%；当合作银行“秦科\\n贷”业务不良率超过 4%时，暂停新增贷款投放，待不良率降至 4%以下，经省科技厅\\n会同省财政厅、省委金融办研究同意后，恢复新增贷款投放。对合作银行“秦科贷”业\\n务不良率超过 4%的部分，省风险补偿资金不予补偿。 \\n第五章  绩效与监督管理 \\n第二十三条  省科技厅会同省财政厅、省委金融办开展年度绩效评价，重点评价合\\n作银行贷款投放规模、支持企业数量、融资成本、不良贷款率等指标，评价结果适时\\n通报。 \\n第二十四条  省科技厅会同省财政厅、省委金融办对“秦科贷”风险补偿业务开展不\\n定期监督检查，动态掌握资金使用与管理情况。 \\n— 第 6 页 — \\n第二十五条  本细则未尽事宜，按照《陕西省中小微企业银行贷款风险补偿资金管\\n理办法》（陕财办金〔2026〕9 号）规定执行。 \\n第二十六条  （原文未列，依公开文本留存条文编号连续性。） \\n第二十七条  本细则自印发之日起施行，随省中小微企业银行贷款风险补偿资金实\\n际情况延续执行。 \\n  \\n— 第 7 页 — \\n附  件 \\n附件 1  “秦科贷”风险补偿申请书 \\n××年第×号 \\n \\n填报单位：（公章） \\n \\n贷款编号：__________  统一社会信用代码/身份证号：__________  客户名称：\\n__________ \\n合作银行经办机构：__________  机构名称：__________  联系人：__________  联系电\\n话：__________ \\n借款借据号：__________  贷款金额（元）：__________  贷款到期日：__________ \\n逾期本金（元）：__________  逾期日期：__________  逾期天数：__________ \\n \\n借款人情况：（贷款逾期详情及产生原因；客户资产、负债等现状） \\n \\n追偿措施和进展情况：（贷款逾期后银行采取的应对措施，目前追偿进展情况） \\n \\n风险补偿申请： \\n我行向该客户发放的“秦科贷”贷款发生逾期，我行已对该客户启动追偿程序，向\\n法院提起诉讼，且法院已依法受理。根据《陕西省中小微企业银行贷款风险补偿资金\\n管理办法》（陕财办金〔2026〕9 号）和《陕西省中小微科技企业银行贷款（秦科\\n贷）风险补偿实施细则》（陕财办金〔2026〕23 号），我行申请该笔贷款的风险补\\n偿。申请风险补偿金额为________元，请予审批。 \\n上述补偿款请拨付至如下账户：________________________________。 \\n附件 2  “秦科贷”风险补偿通知书 \\n根据《陕西省中小微企业银行贷款风险补偿资金管理办法》（陕财办金〔2026〕9\\n号）及《陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则》（陕财办金\\n— 第 8 页 — \\n〔2026〕23 号），按照逾期本金的____%承担风险补偿，现拨付你行风险补偿资金\\n________元。请做好逾期贷款追偿工作，追偿资金按照规定返还。 \\n附件 3  风险补偿资金返还告知书 \\n告知事项：合作银行追偿或处置所得资金，扣除合理费用后，须在资金到账之日\\n起 10 个工作日内，按原风险分担比例返还至省风险补偿资金池，并书面报告省财政\\n厅、省科技厅及托管机构。 \\n  \\n— 第 9 页 — \\n文件出处说明 \\n发文机关：陕西省财政厅、陕西省科学技术厅、中共陕西省委金融委员会办公室 \\n发文字号：陕财办金〔2026〕23 号 \\n成文日期：2026 年 7 月 1 日 \\n原文来源（陕西省财政厅供稿、陕西股权交易中心转载全文）： \\nhttp://mp.weixin.qq.com/s?__biz=MjM5OTQ0NjUzNw==&mid=2650489715&idx=2&sn=d49d574f9d9d7a2bc\\n18b17056a73283e \\n政策解读（陕西省财政厅官方）： \\nhttp://mp.weixin.qq.com/s?__biz=MjM5MTQ4MzQxNw==&mid=2649371235&idx=6&sn=73a7513afaa6f8d6\\n741fad2c5045c1a1 \\n说明：本文件为转载全文整理，条款以官方正式印发文本为准。如需盖章红头原件，\\n可向省科技厅成果转化处或省财政厅金融处索取。\", \"filename\": \"陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"parsingIssues\": [], \"submittedBy\": 1, \"evidenceHistory\": [{\"officialMetadata\": {\"title\": \"陕财办金〔2026〕23号 秦科贷风险补偿实施细则\", \"documentNo\": \"陕财办金〔2026〕23号\", \"issuer\": \"国务院及国家有关部委\", \"sourceUrl\": \"/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"cc150b8cb52b2efc431525db2f8a0d2d0cafbaee24d06b9a80bd4649f001f368\", \"validitySourceUrl\": \"/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}], \"chunks\": [{\"ordinal\": 1, \"startOffset\": 0, \"endOffset\": 763, \"text\": \"— 第 1 页 — \\n陕西省财政厅 陕西省科学技术厅 中共陕西省委金融委员会办公室 \\n关于印发《陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则》的通知  \\n各设区市、杨凌示范区财政局、科技局，西安市委金融办、各设区市地方金融管理部\\n门、杨凌示范区地方金融监管局，有关金融机构： \\n为贯彻落实国家和省委、省政府关于做好科技金融首篇大文章的决策部署，引导\\n金融机构加大对科技企业的融资支持力度，促进科技、产业、金融实现深度融合与良\\n性循环，推动金融资源向科技创新领域集聚。 \\n经研究，决定在陕西省中小微企业贷款风险补偿资金项下设立陕西省中小微科技\\n企业银行贷款（秦科贷）风险补偿资金。 \\n为保障风险补偿工作安全、高效、规范运行，结合工作实际，特制定《陕西省中\\n小微科技企业银行贷款（秦科贷）风险补偿实施细则》。 \\n现予印发实施，请遵照执行。 \\n陕西省财政厅  陕西省科学技术厅  中共陕西省委金融委员会办公室 \\n2026 年 7 月 1 日 \\n  \\n— 第 2 页 — \\n陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则  \\n第一章  总  则 \\n第一条  为贯彻落实国家和省委、省政府关于做好科技金融首篇大文章的决策部\\n署，引导金融机构加大对科技企业的融资支持力度，促进科技、产业、金融实现深度\\n融合与良性循环，推动金融资源向科技创新领域集聚，按照《陕西省财政厅等七部门\\n关于修订印发〈陕西省中小微企业银行贷款风险补偿资金管理办法〉的通知》（陕财\\n办金〔2026〕9 号）工作要求，制定本细则。 \\n第二条  “秦科贷”是省科技厅会同省财政厅、省委金融办，在省中小微企业银行贷\\n款风险补偿资金（以下简称“省风险补偿资金”）项下设立的子项目，重点支持科技企\\n业通过信用、科技成果、人才、股权、无形资产等获得的贷款。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 2, \"startOffset\": 683, \"endOffset\": 1465, \"text\": \"在省中小微企业银行贷\\n款风险补偿资金（以下简称“省风险补偿资金”）项下设立的子项目，重点支持科技企\\n业通过信用、科技成果、人才、股权、无形资产等获得的贷款。 \\n第三条  “秦科贷”风险补偿资金适用企业名录：申报省级科技计划项目、提名省科\\n学技术奖的科技企业；创新积分制优质科技企业；与省科技厅建立合作关系的投资\\n（保险）机构已投（已保）科技企业。 \\n第二章  合作银行的确定 \\n第四条  省科技厅会同省财政厅、省委金融办发布“秦科贷”合作银行申报通知，符\\n合条件的银行业金融机构按要求提交书面申请。意向银行由其总行或省级分行（一级\\n分支机构）统一申报。 \\n第五条  省科技厅会同省财政厅、省委金融办按照本细则及申报通知要求开展评\\n审，择优确定合作银行，优先选择： \\n（一）纳入科技金融常态化推送机制的银行； \\n（二）服务中小微科技企业数量大、贷款多、利率低的银行； \\n（三）设立科技信贷产品、建立科技贷款绿色通道、风险防控体系健全、科技金\\n融服务能力突出的银行。 \\n第六条  省科技厅与合作银行、托管机构签订三方合作协议，原则上合作期限为 3\\n年。 \\n第七条  省科技厅会同省财政厅、省委金融办对合作银行实行年度考核评价，考核\\n不合格的，视情况暂停或取消合作资格，并可根据工作需要适时增补合作银行。 \\n— 第 3 页 — \\n第三章  管理职责与分工 \\n第八条  省财政厅负责筹措安排、审核拨付省风险补偿资金；参与合作银行遴选、\\n考核评价与绩效管理。 \\n第九条  省科技厅负责建立并动态管理“秦科贷”风险补偿资金适用企业名录；牵头\\n开展合作银行遴选；审核合作银行提交的风险补偿申请；组织实施合作银行考核评价\\n与绩效管理。 \\n第十条  省委金融办负责指导金融机构加大对“秦科贷”适用企业信贷投放，加强政\\n策宣传与银企融资对接；参与合作银行遴选、考核评价与绩效管理。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 3, \"startOffset\": 1385, \"endOffset\": 2177, \"text\": \"与绩效管理。 \\n第十条  省委金融办负责指导金融机构加大对“秦科贷”适用企业信贷投放，加强政\\n策宣传与银企融资对接；参与合作银行遴选、考核评价与绩效管理。 \\n第十一条  合作银行负责建立健全“秦科贷”工作机制，优化业务流程，提升放款效\\n率，做好企业融资服务；与“秦科贷”适用企业自主对接，独立审核、发放贷款；按季\\n度向托管机构报送贷款投放、不良贷款等数据；如实申报风险补偿，做好不良贷款追\\n偿、风险处置及追偿资金清算返还；配合相关部门开展数据核查、绩效评价与监督检\\n查。 \\n第十二条  托管机构负责按季度统计合作银行“秦科贷”业务开展情况，并报送省财\\n政厅、省科技厅、省委金融办；受理合作银行风险补偿申请并出具初审意见；按规定\\n及时拨付补偿资金；按年度向省财政厅报送资金运行报告；配合相关部门开展绩效评\\n价与监督检查。 \\n第四章  补偿条件与程序 \\n第十三条  贷款额度。省财政厅会同省科技厅根据省风险补偿资金规模、不良贷款\\n情况等，可对“秦科贷”采取设定年度投放额度上限、实施余额管控等措施。“秦科贷”\\n单户贷款额度最高 3000 万元。 \\n第十四条  贷款期限。根据企业生产经营周期合理确定，原则上不超过 3 年，中长\\n期项目可延长至 5 年。 \\n第十五条  贷款利率。原则上不超过同期贷款市场报价利率（LPR）+100BP。合\\n作银行不得另外收取贷款保证金、融资手续费等任何其他费用。 \\n第十六条  担保方式。单户贷款额度不超过 500 万元的，以信用方式投放，企业无\\n需提供抵押、质押等担保措施；对于单户贷款额度超过 500 万元的，可追加其他抵\\n— 第 4 页 — \\n押、质押措施。 \\n第十七条  补偿条件。“秦科贷”风险补偿对象为确定的合作银行，申请补偿须同时\\n满足以下条件： \\n（一）贷款对象应纳入“秦科贷”企业名录，且为签订合作协议后新发放贷款形成\\n的不良贷款；\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 4, \"startOffset\": 2097, \"endOffset\": 2883, \"text\": \"科贷”风险补偿对象为确定的合作银行，申请补偿须同时\\n满足以下条件： \\n（一）贷款对象应纳入“秦科贷”企业名录，且为签订合作协议后新发放贷款形成\\n的不良贷款； \\n（二）贷款符合本细则关于贷款额度、贷款期限、贷款利率等要求； \\n（三）贷款资金仅限用于企业和科技创新相关的日常生产经营活动，不得用于偿\\n还企业其他借款，不得用于金融投资、理财等套利活动，不得用于投资国家产业政策\\n禁止和限制的项目。 \\n第十八条  不良贷款认定与补偿标准。“秦科贷”贷款本金逾期满 90 天仍无法收\\n回，且合作银行已向人民法院提起诉讼并取得立案通知书；或贷款虽未逾期满 90 天但\\n已进入司法追偿程序的，认定为不良贷款，合作银行可启动风险补偿申请程序。对确\\n认的不良贷款本金余额，按以下比例给予风险补偿： \\n（一）“首贷”企业融资。单户贷款金额 500 万元（含）以内的，补偿比例为\\n70%；单户贷款金额 500 万元（不含）—1000 万元（含）的，补偿比例为 60%；单户\\n贷款金额 1000 万元（不含）—3000 万元（含）的，补偿比例为 50%。 \\n（二）非“首贷”企业融资。单户贷款金额不超过 1000 万元（含）的，补偿比例为\\n50%；单户贷款金额 1000 万元（不含）—3000 万元（含）的，补偿比例为 40%。 \\n风险补偿比例汇总表： \\n企业类型 贷款金额区间 风险补偿比例 \\n首贷企业 ≤500 万元（含） 70% \\n首贷企业 500 万元（不含）—1000 万元\\n（含） \\n60% \\n首贷企业 1000 万元（不含）—3000 万元\\n（含） \\n50% \\n非首贷企业 ≤1000 万元（含） 50% \\n非首贷企业 1000 万元（不含）—3000 万元\\n（含） \\n40% \\n— 第 5 页 — \\n第十九条  单户企业在“秦科贷”风险补偿资金下每次只能申请一笔贷款（同一借款\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 5, \"startOffset\": 2803, \"endOffset\": 3602, \"text\": \"1000 万元（不含）—3000 万元\\n（含） \\n40% \\n— 第 5 页 — \\n第十九条  单户企业在“秦科贷”风险补偿资金下每次只能申请一笔贷款（同一借款\\n合同项下多笔支用、多张借据统一认定为单笔贷款，借据须与对应借款合同一一对\\n应，且限于同一自然年度），且不得在其他中小微企业银行贷款风险补偿资金子项目\\n下同时申请贷款；已享受过市（县）设立的风险补偿资金支持的贷款不得再申请“秦科\\n贷”政策支持。 \\n第二十条  补偿流程。 \\n（一）合作银行于每季度结束后 5 个工作日内向托管机构提交风险补偿申请材\\n料，包括风险补偿申请书，贷款合同、放款凭证等贷款发放证明材料，以及逾期证\\n明、不良认定、司法立案材料等其他必要材料； \\n（二）托管机构在 5 个工作日内完成合规性审核并出具审核意见； \\n（三）省科技厅在 5 个工作日内完成复审，必要时开展实地核查； \\n（四）省财政厅对符合补偿条件的，在复核结束后 5 个工作日内通知托管机构拨\\n付省风险补偿资金。 \\n第二十一条  追偿与资金返还。风险补偿资金拨付后，合作银行应继续采取有效措\\n施追偿不良贷款。合作银行追偿或处置所得资金，扣除合理费用后，须在资金到账之\\n日起 10 个工作日内，按原风险分担比例返还至省风险补偿资金池，并书面报告省财政\\n厅、省科技厅及托管机构。 \\n第二十二条  “秦科贷”业务整体贷款不良率原则上不超过 4%；当合作银行“秦科\\n贷”业务不良率超过 4%时，暂停新增贷款投放，待不良率降至 4%以下，经省科技厅\\n会同省财政厅、省委金融办研究同意后，恢复新增贷款投放。对合作银行“秦科贷”业\\n务不良率超过 4%的部分，省风险补偿资金不予补偿。 \\n第五章  绩效与监督管理 \\n第二十三条  省科技厅会同省财政厅、省委金融办开展年度绩效评价，重点评价合\\n作银行贷款投放规模、支持企业数量、融资成本、不良贷款率等指标，评价结果适时\\n通报。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 6, \"startOffset\": 3522, \"endOffset\": 4285, \"text\": \"第二十三条  省科技厅会同省财政厅、省委金融办开展年度绩效评价，重点评价合\\n作银行贷款投放规模、支持企业数量、融资成本、不良贷款率等指标，评价结果适时\\n通报。 \\n第二十四条  省科技厅会同省财政厅、省委金融办对“秦科贷”风险补偿业务开展不\\n定期监督检查，动态掌握资金使用与管理情况。 \\n— 第 6 页 — \\n第二十五条  本细则未尽事宜，按照《陕西省中小微企业银行贷款风险补偿资金管\\n理办法》（陕财办金〔2026〕9 号）规定执行。 \\n第二十六条  （原文未列，依公开文本留存条文编号连续性。） \\n第二十七条  本细则自印发之日起施行，随省中小微企业银行贷款风险补偿资金实\\n际情况延续执行。 \\n  \\n— 第 7 页 — \\n附  件 \\n附件 1  “秦科贷”风险补偿申请书 \\n××年第×号 \\n \\n填报单位：（公章） \\n \\n贷款编号：__________  统一社会信用代码/身份证号：__________  客户名称：\\n__________ \\n合作银行经办机构：__________  机构名称：__________  联系人：__________  联系电\\n话：__________ \\n借款借据号：__________  贷款金额（元）：__________  贷款到期日：__________ \\n逾期本金（元）：__________  逾期日期：__________  逾期天数：__________ \\n \\n借款人情况：（贷款逾期详情及产生原因；客户资产、负债等现状） \\n \\n追偿措施和进展情况：（贷款逾期后银行采取的应对措施，目前追偿进展情况） \\n \\n风险补偿申请： \\n我行向该客户发放的“秦科贷”贷款发生逾期，我行已对该客户启动追偿程序，向\\n法院提起诉讼，且法院已依法受理。根据《陕西省中小微企业银行贷款风险补偿资金\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 7, \"startOffset\": 4205, \"endOffset\": 4994, \"text\": \"申请： \\n我行向该客户发放的“秦科贷”贷款发生逾期，我行已对该客户启动追偿程序，向\\n法院提起诉讼，且法院已依法受理。根据《陕西省中小微企业银行贷款风险补偿资金\\n管理办法》（陕财办金〔2026〕9 号）和《陕西省中小微科技企业银行贷款（秦科\\n贷）风险补偿实施细则》（陕财办金〔2026〕23 号），我行申请该笔贷款的风险补\\n偿。申请风险补偿金额为________元，请予审批。 \\n上述补偿款请拨付至如下账户：________________________________。 \\n附件 2  “秦科贷”风险补偿通知书 \\n根据《陕西省中小微企业银行贷款风险补偿资金管理办法》（陕财办金〔2026〕9\\n号）及《陕西省中小微科技企业银行贷款（秦科贷）风险补偿实施细则》（陕财办金\\n— 第 8 页 — \\n〔2026〕23 号），按照逾期本金的____%承担风险补偿，现拨付你行风险补偿资金\\n________元。请做好逾期贷款追偿工作，追偿资金按照规定返还。 \\n附件 3  风险补偿资金返还告知书 \\n告知事项：合作银行追偿或处置所得资金，扣除合理费用后，须在资金到账之日\\n起 10 个工作日内，按原风险分担比例返还至省风险补偿资金池，并书面报告省财政\\n厅、省科技厅及托管机构。 \\n  \\n— 第 9 页 — \\n文件出处说明 \\n发文机关：陕西省财政厅、陕西省科学技术厅、中共陕西省委金融委员会办公室 \\n发文字号：陕财办金〔2026〕23 号 \\n成文日期：2026 年 7 月 1 日 \\n原文来源（陕西省财政厅供稿、陕西股权交易中心转载全文）： \\nhttp://mp.weixin.qq.com/s?__biz=MjM5OTQ0NjUzNw==&mid=2650489715&idx=2&sn=d49d574f9d9d7a2bc\\n18b17056a73283e \\n政策解读（陕西省财政厅官方）：\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 8, \"startOffset\": 4914, \"endOffset\": 5162, \"text\": \"w==&mid=2650489715&idx=2&sn=d49d574f9d9d7a2bc\\n18b17056a73283e \\n政策解读（陕西省财政厅官方）： \\nhttp://mp.weixin.qq.com/s?__biz=MjM5MTQ4MzQxNw==&mid=2649371235&idx=6&sn=73a7513afaa6f8d6\\n741fad2c5045c1a1 \\n说明：本文件为转载全文整理，条款以官方正式印发文本为准。如需盖章红头原件，\\n可向省科技厅成果转化处或省财政厅金融处索取。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}], \"chunking\": {\"category\": \"FINANCE_POLICY\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 800, \"overlap\": 80, \"delimiterRegex\": null}, \"pages\": []}',NULL,'PASS','2026-09-20 15:55:40','/files/finance-policy/陕财办金〔2026〕23号_秦科贷风险补偿实施细则.pdf'),('237c900e-6384-5ffb-8ce4-8851e98f50cb',1,'{\"report\": {\"id\": \"237c900e-6384-5ffb-8ce4-8851e98f50cb\", \"createdAt\": \"2026-09-20T15:54:33\", \"metadata\": {\"title\": \"工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知\", \"documentNo\": \"\", \"issuer\": \"工业和信息化部\", \"sourceUrl\": \"/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"textHash\": \"ed8e9266affe8527a7cd8d7533679f11be19c0fad968c72520d4c0c1e9bc2cd8\", \"decision\": \"PASS\", \"score\": 100, \"scores\": {\"ENCODING\": 100, \"AUTHENTICITY\": 100, \"FORMAT\": 100, \"QUALITY\": 100}, \"issues\": [], \"evidence\": {\"officialMetadata\": {\"title\": \"工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知\", \"documentNo\": \"\", \"issuer\": \"工业和信息化部\", \"sourceUrl\": \"/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"ed8e9266affe8527a7cd8d7533679f11be19c0fad968c72520d4c0c1e9bc2cd8\", \"validitySourceUrl\": \"/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}, \"admitted\": true, \"chunkCount\": 13, \"workflowStatus\": \"APPROVED\", \"aiModel\": \"manual-import\", \"aiCompletedAt\": \"2026-09-20T15:54:33\", \"manualReviewerId\": 1, \"manualReviewedAt\": \"2026-09-20T15:54:33\", \"manualNote\": \"批量导入：已审核通过并发布到金融政策库。\"}, \"text\": \"1\\n优质中小企业梯度培育管理暂行办法\\n第一章 总则\\n第一条 为提升中小企业创新能力和专业化水平，促进中小\\n企业高质量发展，助力实现产业基础高级化和产业链现代化，\\n根据《中华人民共和国国民经济和社会发展第十四个五年规划\\n和2035 年远景目标纲要》《“十四五”促进中小企业发展规划》\\n《关于健全支持中小企业发展制度的若干意见》，制定本办法。\\n第二条 优质中小企业是指在产品、技术、管理、模式等方\\n面创新能力强、专注细分市场、成长性好的中小企业，由创新\\n型中小企业、专精特新中小企业和专精特新“小巨人”企业三\\n个层次组成。创新型中小企业具有较高专业化水平、较强创新\\n能力和发展潜力，是优质中小企业的基础力量；专精特新中小\\n企业实现专业化、精细化、特色化发展，创新能力强、质量效\\n益好，是优质中小企业的中坚力量；专精特新“小巨人”企业\\n位于产业基础核心领域、产业链关键环节，创新能力突出、掌\\n握核心技术、细分市场占有率高、质量效益好，是优质中小企\\n业的核心力量。\\n2\\n第三条 参评优质中小企业应在中华人民共和国境内工商\\n注册登记、具有独立法人资格，符合《中小企业划型标准规定》，\\n企业未被列入经营异常名录或严重失信主体名单，提供的产品\\n（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生\\n重大安全（含网络安全、数据安全）、质量、环境污染等事故以\\n及偷漏税等违法违规行为。\\n第四条 优质中小企业梯度培育工作，坚持完整、准确、全\\n面贯彻新发展理念，坚持专精特新发展方向，坚持有效市场与\\n有为政府相结合，坚持分层分类分级指导，坚持动态管理和精\\n准服务。\\n第五条 工业和信息化部负责优质中小企业梯度培育工作\\n的宏观指导、统筹协调和监督检查，推动出台相关支持政策，\\n发布相关评价和认定标准，负责专精特新“小巨人”企业认定\\n工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵\\n团中小企业主管部门（以下简称省级中小企业主管部门）根据\\n本办法制定细则，报工业和信息化部备案，并依据细则负责本\\n地区优质中小企业梯度培育工作，负责专精特新中小企业认定\\n和创新型中小企业评价工作。其他机构不得开展与创新型中小\\n企业、专精特新中小企业、专精特新“小巨人”企业有关的评\\n价、认定、授牌等活动。\\n第六条 各级中小企业主管部门应强化优质中小企业的动\\n3\\n态管理，建立健全“有进有出”的动态管理机制。“十四五”期\\n间，努力在全国推动培育一百万家创新型中小企业、十万家专\\n精特新中小企业、一万家专精特新“小巨人”企业。\\n第七条 工业和信息化部建设优质中小企业梯度培育平台\\n（https://zjtx.miit.gov.cn/，以下简称培育平台），搭建优质中小\\n企业数据库。各级中小企业主管部门应加强服务对接和监测分\\n析，对企业运行、发展态势、意见诉求，以及扶持政策与培育\\n成效等开展定期和不定期跟踪，有针对性地制定政策和开展精\\n准服务；进一步落实“放管服”要求，推动涉企数据互通共享，\\n减轻企业数据填报负担。\\n第二章 评价和认定\\n第八条 优质中小企业评价和认定工作坚持政策引领、企业\\n自愿、培育促进、公开透明的原则，按照“谁推荐、谁把关，\\n谁审核、谁管理”方式统筹开展、有序推进。\\n第九条 工业和信息化部发布并适时更新创新型中小企业\\n评价标准（附件1）、专精特新中小企业认定标准（附件2）和\\n专精特新“小巨人”企业认定标准（附件3）。专精特新中小企\\n业认定标准中的“特色化指标”，由省级中小企业主管部门结合\\n本地产业状况和中小企业发展实际设定并发布。\\n4\\n第十条 创新型中小企业评价，由企业按属地原则自愿登录\\n培育平台参与自评，省级中小企业主管部门根据评价标准，组\\n织对企业自评信息和相关佐证材料进行审核、实地抽查和公示。\\n公示无异议的，由省级中小企业主管部门公告为创新型中小企\\n业。\\n第十一条 专精特新中小企业认定，由创新型中小企业按属\\n地原则自愿提出申请，省级中小企业主管部门根据认定标准，\\n组织对企业申请材料和相关佐证材料进行审核、实地抽查和公\\n示。公示无异议的，由省级中小企业主管部门认定为专精特新\\n中小企业。\\n第十二条 专精特新“小巨人”企业认定，由专精特新中小\\n企业按属地原则自愿提出申请，省级中小企业主管部门根据认\\n定标准，对企业申请材料和相关佐证材料进行初审和实地抽查，\\n初审通过的向工业和信息化部推荐。工业和信息化部组织对被\\n推荐企业进行审核、抽查和公示。公示无异议的，由工业和信\\n息化部认定为专精特新“小巨人”企业。\\n原则上每年第二季度组织开展专精特新“小巨人”企业认\\n定工作，省级中小企业主管部门应根据工作要求，统筹做好创\\n新型中小企业评价、专精特新中小企业认定和专精特新“小巨\\n人”企业推荐工作。\\n5\\n第三章 动态管理\\n第十三条 经公告的创新型中小企业有效期为三年，每次到\\n期后由企业重新登录培育平台进行自评，经省级中小企业主管\\n部门审核（含实地抽查）通过后，有效期延长三年。经认定的\\n专精特新中小企业、专精特新“小巨人”企业有效期为三年，\\n每次到期后由认定部门组织复核（含实地抽查），复核通过的，\\n有效期延长三年。\\n第十四条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，应在每年4 月30 日前通过培育平\\n台更新企业信息。未及时更新企业信息的，取消复核资格。\\n第十五条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，如发生更名、合并、重组、跨省\\n迁移、设立境外分支机构等与评价认定条件有关的重大变化，\\n应在发生变化后的3 个月内登录培育平台，填写重大变化情况\\n报告表。不再符合评价或认定标准的创新型中小企业和专精特\\n新中小企业，由省级中小企业主管部门核实后取消公告或认定；\\n不再符合认定标准的专精特新“小巨人”企业，由省级中小企\\n业主管部门核实后报工业和信息化部，由工业和信息化部取消\\n认定。对于未在3 个月内报告重大变化情况的，取消复核资格，\\n或直接取消公告或认定。\\n6\\n第十六条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，如发生重大安全（含网络安全、\\n数据安全）、质量、环境污染等事故，或严重失信、偷漏税等违\\n法违规行为，或被发现存在数据造假等情形，直接取消公告或\\n认定，且至少三年内不得再次申报。\\n第十七条 任何组织和个人可针对创新型中小企业、专精特\\n新中小企业和专精特新“小巨人”企业相关信息真实性、准确\\n性等方面存在的问题，向相应中小企业主管部门实名举报，并\\n提供佐证材料和联系方式。对受理的举报内容，相应中小企业\\n主管部门应及时向被举报企业核实，被举报企业未按要求回复\\n或经核实确认该企业存在弄虚作假行为的，视情节轻重要求企\\n业进行整改，或直接取消公告或认定。\\n第四章 培育扶持\\n第十八条 中小企业主管部门应针对本地区不同发展阶段、\\n不同类型中小企业的特点和需求，建立优质中小企业梯度培育\\n体系，制定分层分类的专项扶持政策，加大服务力度，维护企\\n业合法权益，不断优化中小企业发展环境，激发涌现一大批专\\n精特新企业。\\n第十九条 中小企业主管部门应发挥促进中小企业发展工\\n作协调机制作用，加强部门协同、上下联动，形成工作合力。\\n7\\n统筹运用财税、金融、技术、产业、人才、用地、用能等政策\\n工具持续支持优质中小企业发展，提高政策精准性和有效性。\\n第二十条 中小企业主管部门应着力构建政府公共服务、市\\n场化服务、公益性服务协同促进的服务体系，通过搭建创新成\\n果对接、大中小企业融通创新、创新创业大赛、供需对接等平\\n台，汇聚服务资源，创新服务方式，为中小企业提供全周期、\\n全方位、多层次的服务。通过普惠服务与精准服务相结合，着\\n力提升服务的广度、深度、精准度和响应速度，增强企业获得\\n感。\\n第二十一条 中小企业主管部门和各类中小企业服务机构\\n应加强指导和服务，促进中小企业提升公司治理、精细管理和\\n合规管理水平，防范各类风险，推动持续健康发展，切实发挥\\n优质中小企业示范作用。在评价、认定和服务过程中应注重对\\n企业商业秘密的保护，在宣传报道、考察交流前，应征得企业\\n同意。\\n第五章 附则\\n第二十二条 本办法由工业和信息化部负责解释。\\n第二十三条 本办法自2022 年8 月1 日起实施。8 月1 日前\\n已被省级中小企业主管部门认定的专精特新中小企业和已被工\\n业和信息化部认定的专精特新“小巨人”企业，继续有效。有\\n8\\n效期（最长不超过3 年）到期后自动失效，复核时按本办法执\\n行。\\n附件：1.创新型中小企业评价标准\\n2.专精特新中小企业认定标准\\n3.专精特新“小巨人”企业认定标准\\n4.部分指标和要求说明\\n9\\n附件1\\n创新型中小企业评价标准\\n一、公告条件\\n评价得分达到60 分以上（其中创新能力指标得分不低\\n于20 分、成长性指标及专业化指标得分均不低于15 分），\\n或满足下列条件之一：\\n（一）近三年内获得过国家级、省级科技奖励。\\n（二）获得高新技术企业、国家级技术创新示范企业、\\n知识产权优势企业和知识产权示范企业等荣誉（均为有效期\\n内）。\\n（三）拥有经认定的省部级以上研发机构。\\n（四）近三年新增股权融资总额（合格机构投资者的实\\n缴额）500万元以上。\\n二、评价指标\\n包括创新能力、成长性、专业化三类六个指标，评价结\\n果依分值计算，满分为100 分。\\n（一）创新能力指标（满分40分）\\n1.与企业主导产品相关的有效知识产权数量（满分20分）\\nA.Ⅰ类高价值知识产权1项以上（20分）\\nB. 自主研发的Ⅰ类知识产权1项以上（15分）\\nC.Ⅰ类知识产权1项以上（10分）\\n10\\nD.Ⅱ类知识产权1项以上（5分）\\nE. 无（0分）\\n2.上年度研发费用总额占营业收入总额比重（满分20分）\\nA.5%以上（20分）\\nB.3%-5%（15分）\\nC.2%-3%（10分）\\nD.1%-2%（5分）\\nE.1%以下（0分）\\n（二）成长性指标（满分30分）\\n3.上年度主营业务收入增长率（满分20分）\\nA.15%以上（20分）\\nB.10%-15%（15分）\\nC.5%-10%（10分）\\nD.0%-5%（5分）\\nE.0%以下（0分）\\n4.上年度资产负债率（满分10分）\\nA.55%以下（10分）\\nB.55%-75%（5分）\\nC.75%以上（0分）\\n（三）专业化指标（满分30分）\\n5.主导产品所属领域情况（满分10分）\\nA.属于《战略性新兴产业分类》（10分）\\n11\\nB.属于其他领域（5分）\\n6.上年度主营业务收入总额占营业收入总额比重（满分\\n20分）\\nA.70%以上（20分）\\nB.60%-70%（15分）\\nC.55%-60%（10分）\\nD.50%-55%（5分）\\nE.50%以下（0分）\\n12\\n附件2\\n专精特新中小企业认定标准\\n一、认定条件\\n同时满足以下四项条件即视为满足认定条件：\\n（一）从事特定细分市场时间达到2 年以上。\\n（二）上年度研发费用总额不低于100 万元，且占营业\\n收入总额比重不低于3%。\\n（三）上年度营业收入总额在1000 万元以上，或上年\\n度营业收入总额在1000 万元以下，但近2 年新增股权融资\\n总额（合格机构投资者的实缴额）达到2000 万元以上。\\n（四）评价得分达到60 分以上或满足下列条件之一：\\n1.近三年获得过省级科技奖励，并在获奖单位中排名前\\n三；或获得国家级科技奖励，并在获奖单位中排名前五。\\n2.近两年研发费用总额均值在1000万元以上。\\n3.近两年新增股权融资总额（合格机构投资者的实缴额）\\n6000万元以上。\\n4.近三年进入“创客中国”中小企业创新创业大赛全国\\n500强企业组名单。\\n二、评价指标\\n包括专业化、精细化、特色化和创新能力四类十三个指\\n标，评价结果依分值计算，满分为100 分。\\n13\\n（一）专业化指标（满分 25 分）\\n1.上年度主营业务收入总额占营业收入总额比重（满分\\n5 分）\\nA.80%以上（5 分）\\nB.70%-80%（3 分）\\nC.60%-70%（1 分）\\nD.60%以下（0 分）\\n2.近 2 年主营业务收入平均增长率（满分 10 分）\\nA.10%以上（10 分）\\nB.8%-10%（8 分）\\nC.6%-8%（6 分）\\nD.4%-6%（4 分）\\nE.0%-4%（2 分）\\nF.0%以下（0 分）\\n3.从事特定细分市场年限（满分 5 分）\\n每满2 年得1 分，最高不超过5 分。\\n4.主导产品所属领域情况（满分 5 分）\\nA. 在产业链供应链关键环节及关键领域“补短板”“锻\\n长板”“填空白”取得实际成效（5 分）\\nB. 属于工业“六基”领域、中华老字号名录或企业主导\\n产品服务关键产业链重点龙头企业（3 分）\\nC. 不属于以上情况（0 分）\\n14\\n（二）精细化指标（满分 25 分）\\n5.数字化水平（满分 5 分）\\nA. 三级以上（5 分）\\nB. 二级（3 分）\\nC. 一级（0 分）\\n6.质量管理水平（每满足一项加 3 分，最高不超过 5 分）\\nA. 获得省级以上质量奖荣誉\\nB. 建立质量管理体系，获得ISO9001 等质量管理体系\\n认证证书\\nC. 拥有自主品牌\\nD. 参与制修订标准\\n7.上年度净利润率（满分 10 分）\\nA.10%以上（10 分）\\nB.8%-10%（8 分）\\nC.6%-8%（6 分）\\nD.4%-6%（4 分）\\nE.2%-4%（2 分）\\nF.2%以下（0 分）\\n8.上年度资产负债率（满分 5 分）\\nA.50%以下（5 分）\\nB.50%-60%（3 分）\\nC.60%-70%（1 分）\\n15\\nD.70%以上（0 分）\\n（三）特色化指标（满分 15 分）\\n9.地方特色指标。由省级中小企业主管部门结合本地产\\n业状况和中小企业发展实际自主设定 1-3 个指标进行评价\\n（满分 15 分）\\n（四）创新能力指标（满分 35 分）\\n10.与企业主导产品相关的有效知识产权数量（满分 10\\n分）\\nA.Ⅰ类高价值知识产权1项以上（10分）\\nB. 自主研发Ⅰ类知识产权1项以上（8分）\\nC.Ⅰ类知识产权1项以上（6分）\\nD.Ⅱ类知识产权1项以上（2分）\\nE. 无（0分）\\n11.上年度研发费用投入（满分 10 分）\\nA. 研发费用总额500 万元以上或研发费用总额占营业\\n收入总额比重在10%以上（10 分）\\nB. 研发费用总额 400-500 万元或研发费用总额占营业\\n收入总额比重在8%-10%（8 分）\\nC. 研发费用总额 300-400 万元或研发费用总额占营业\\n收入总额比重在6%-8%（6 分）\\nD. 研发费用总额 200-300 万元或研发费用总额占营业\\n收入总额比重在4%-6%（4 分）\\n16\\nE. 研发费用总额100-200 万元或研发费用总额占营业收\\n入总额比重在3%-4%（2 分）\\nF. 不属于以上情况（0 分）\\n12.上年度研发人员占比（满分 5 分）\\nA.20%以上（5 分）\\nB.10%-20%（3 分）\\nC.5%-10%（1 分）\\nD.5%以下（0 分）\\n13.建立研发机构级别（满分 10 分）\\nA. 国家级（10 分）\\nB. 省级（8 分）\\nC. 市级（4 分）\\nD. 市级以下（2 分）\\nE. 未建立研发机构（0 分）\\n17\\n附件3\\n专精特新“小巨人”企业认定标准\\n专精特新“小巨人”企业认定需同时满足专、精、特、\\n新、链、品六个方面指标。\\n一、专业化指标\\n坚持专业化发展道路，长期专注并深耕于产业链某一环\\n节或某一产品。截至上年末，企业从事特定细分市场时间达\\n到3 年以上，主营业务收入总额占营业收入总额比重不低于\\n70%，近2 年主营业务收入平均增长率不低于5%。\\n二、精细化指标\\n重视并实施长期发展战略，公司治理规范、信誉良好、\\n社会责任感强，生产技术、工艺及产品质量性能国内领先，\\n注重数字化、绿色化发展，在研发设计、生产制造、供应链\\n管理等环节，至少1 项核心业务采用信息系统支撑。取得相\\n关管理体系认证，或产品通过发达国家和地区产品认证（国\\n际标准协会行业认证）。截至上年末，企业资产负债率不高\\n于70%。\\n三、特色化指标\\n技术和产品有自身独特优势，主导产品在全国细分市场\\n占有率达到10%以上，且享有较高知名度和影响力。拥有直\\n接面向市场并具有竞争优势的自主品牌。\\n四、创新能力指标\\n18\\n满足一般性条件或创新直通条件。\\n（一）一般性条件。需同时满足以下三项：\\n1.上年度营业收入总额在1 亿元以上的企业，近2 年研\\n发费用总额占营业收入总额比重均不低于3%；上年度营业\\n收入总额在5000 万元—1 亿元的企业，近2 年研发费用总额\\n占营业收入总额比重均不低于6%；上年度营业收入总额在\\n5000 万元以下的企业，同时满足近2 年新增股权融资总额（合\\n格机构投资者的实缴额）8000 万元以上，且研发费用总额\\n3000 万元以上、研发人员占企业职工总数比重50%以上。\\n2.自建或与高等院校、科研机构联合建立研发机构，设\\n立技术研究院、企业技术中心、企业工程中心、院士专家工\\n作站、博士后工作站等。\\n3.拥有2 项以上与主导产品相关的Ⅰ类知识产权，且实际\\n应用并已产生经济效益。\\n（二）创新直通条件。满足以下一项即可：\\n1.近三年获得国家级科技奖励，并在获奖单位中排名前\\n三。\\n2.近三年进入“创客中国”中小企业创新创业大赛全国\\n50 强企业组名单。\\n五、产业链配套指标\\n位于产业链关键环节，围绕重点产业链实现关键基础技\\n术和产品的产业化应用，发挥“补短板”“锻长板”“填空白”\\n19\\n等重要作用。\\n六、主导产品所属领域指标\\n主导产品原则上属于以下重点领域：从事细分产品市场\\n属于制造业核心基础零部件、元器件、关键软件、先进基础\\n工艺、关键基础材料和产业技术基础；或符合制造强国战略\\n十大重点产业领域；或属于网络强国建设的信息基础设施、\\n关键核心技术、网络安全、数据安全领域等产品。\\n20\\n附件4\\n部分指标和要求说明\\n（一）指标中如对期限无特殊说明，一般使用企业近1 年\\n的年度数据，具体定义为：指企业上一完整会计年度，以企业\\n上一年度审计报告期末数为准。对于存在子公司或母公司的企\\n业，按财政部印发的《企业会计准则》有关规定执行。\\n（二）所称拥有自主品牌是指主营业务产品或服务具有自\\n主知识产权，且符合下列条件之一：\\n1.产品或服务品牌已经国家知识产权局商标局正式注册。\\n2.产品或服务已经实现收入。\\n（三）所称“Ⅰ类知识产权”包括发明专利（含国防专利）、\\n植物新品种、国家级农作物品种、国家新药、国家一级中药保\\n护品种、集成电路布图设计专有权（均不包含转让未满1 年的\\n知识产权）。\\n（四）所称“Ⅰ类高价值知识产权”须符合以下条件之一：\\n1.在海外有同族专利权的发明专利或在海外取得收入的其\\n他Ⅰ类知识产权，其中专利限G20 成员、新加坡以及欧洲专利\\n局经实质审查后获得授权的发明专利。\\n2.维持年限超过10 年的Ⅰ类知识产权。\\n3.实现较高质押融资金额的Ⅰ类知识产权。\\n21\\n4.获得国家科学技术奖或中国专利奖的Ⅰ类知识产权。\\n（五）所称“Ⅱ类知识产权”包括与主导产品相关的软件\\n著作权（不含商标）、授权后维持超过2 年的实用新型专利或外\\n观设计专利（均不包含转让未满1 年的知识产权）。\\n（六）所称“企业数字化转型水平”是指在优质中小企业\\n梯度培育平台完成数字化水平免费自测，具体自测网址、相关\\n标准等事宜，另行明确。\\n（七）所称“重大安全（含网络安全、数据安全）、质量、\\n环境污染等事故”是指产品安全、生产安全、工程质量安全、\\n环境保护、网络安全等各级监管部门，依据《中华人民共和国\\n安全生产法》《中华人民共和国环境保护法》《生产安全事故报\\n告和调查处理条例》《中华人民共和国网络安全法》《中华人民\\n共和国数据安全法》等法律法规，最高人民法院、最高人民检\\n察院司法解释，部门规章以及地方法规等出具的判定意见。\\n（八）所称“股权融资”是指公司股东稀释部分公司股权\\n给投资人，以增资扩股（出让股权不超过30%）的方式引进新\\n的股东，从而取得公司融资的方式。\\n（九）所称“合格机构投资者”是指符合《创业投资企业\\n管理暂行办法》（发展改革委等10 部门令第39 号）或者《私募\\n投资基金监督管理暂行办法》（证监会令第105 号）相关规定，\\n按照上述规定完成备案且规范运作的创业投资基金及私募股权\\n22\\n投资基金。\\n（十）所称“主导产品”是指企业核心技术在产品中发挥\\n重要作用，且产品收入之和占企业同期营业收入比重超过50%。\\n（十一）所称“主导产品在全国细分市场占有率达到10%\\n以上，且享有较高知名度和影响力”可通过企业自证或其他方\\n式佐证。\\n（十二）所称“省级科技奖励”包括各省、自治区、直辖\\n市科学技术奖的一、二、三等奖；“国家级科技奖励”包括国家\\n科学技术进步奖、国家自然科学奖、国家技术发明奖，以及国\\n防科技奖。\\n（十三）如无特殊说明，所称“以上”、“以下”，包括本数；\\n所称的“超过”，不包括本数。在计算评价指标得分时，如指标\\n值位于两个评分区间边界上，按高分计算得分。\\n（十四）本办法部分指标计算公式\\n近2 年主营业务收入平均增长率=（企业上一年度主营业务\\n收入增长率+企业上上年度主营业务收入增长率）/2。\\n企业上一年度主营业务收入增长率=（企业上一年度主营业\\n务收入总额-企业上上年度主营业务收入总额）/企业上上年度主\\n营业务收入总额*100%。其他年度主营业务收入增长率计算方\\n法以此类推。\\n（十五）所称“被列入经营异常名录”以国家企业信用信\\n23\\n息公示系统（http://www.gsxt.gov.cn）查询结果为准；所称“严\\n重失信主体名单”以信用中国（http://www.creditchina.gov.cn）\\n查询结果为准。\\n（十六）所称“创客中国”中小企业创新创业大赛全国500\\n强、50 强企业组名单是指该大赛2021 年以来正式发布的名单。\", \"filename\": \"工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"parsingIssues\": [], \"submittedBy\": 1, \"evidenceHistory\": [{\"officialMetadata\": {\"title\": \"工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知\", \"documentNo\": \"\", \"issuer\": \"工业和信息化部\", \"sourceUrl\": \"/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"ed8e9266affe8527a7cd8d7533679f11be19c0fad968c72520d4c0c1e9bc2cd8\", \"validitySourceUrl\": \"/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"reviewerId\": 1, \"checkedOn\": \"2026-09-20\"}], \"chunks\": [{\"ordinal\": 1, \"startOffset\": 0, \"endOffset\": 783, \"text\": \"1\\n优质中小企业梯度培育管理暂行办法\\n第一章 总则\\n第一条 为提升中小企业创新能力和专业化水平，促进中小\\n企业高质量发展，助力实现产业基础高级化和产业链现代化，\\n根据《中华人民共和国国民经济和社会发展第十四个五年规划\\n和2035 年远景目标纲要》《“十四五”促进中小企业发展规划》\\n《关于健全支持中小企业发展制度的若干意见》，制定本办法。\\n第二条 优质中小企业是指在产品、技术、管理、模式等方\\n面创新能力强、专注细分市场、成长性好的中小企业，由创新\\n型中小企业、专精特新中小企业和专精特新“小巨人”企业三\\n个层次组成。创新型中小企业具有较高专业化水平、较强创新\\n能力和发展潜力，是优质中小企业的基础力量；专精特新中小\\n企业实现专业化、精细化、特色化发展，创新能力强、质量效\\n益好，是优质中小企业的中坚力量；专精特新“小巨人”企业\\n位于产业基础核心领域、产业链关键环节，创新能力突出、掌\\n握核心技术、细分市场占有率高、质量效益好，是优质中小企\\n业的核心力量。\\n2\\n第三条 参评优质中小企业应在中华人民共和国境内工商\\n注册登记、具有独立法人资格，符合《中小企业划型标准规定》，\\n企业未被列入经营异常名录或严重失信主体名单，提供的产品\\n（服务）不属于国家禁止、限制或淘汰类，同时近三年未发生\\n重大安全（含网络安全、数据安全）、质量、环境污染等事故以\\n及偷漏税等违法违规行为。\\n第四条 优质中小企业梯度培育工作，坚持完整、准确、全\\n面贯彻新发展理念，坚持专精特新发展方向，坚持有效市场与\\n有为政府相结合，坚持分层分类分级指导，坚持动态管理和精\\n准服务。\\n第五条 工业和信息化部负责优质中小企业梯度培育工作\\n的宏观指导、统筹协调和监督检查，推动出台相关支持政策，\\n发布相关评价和认定标准，负责专精特新“小巨人”企业认定\\n工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 2, \"startOffset\": 703, \"endOffset\": 1489, \"text\": \"导、统筹协调和监督检查，推动出台相关支持政策，\\n发布相关评价和认定标准，负责专精特新“小巨人”企业认定\\n工作。各省、自治区、直辖市及计划单列市、新疆生产建设兵\\n团中小企业主管部门（以下简称省级中小企业主管部门）根据\\n本办法制定细则，报工业和信息化部备案，并依据细则负责本\\n地区优质中小企业梯度培育工作，负责专精特新中小企业认定\\n和创新型中小企业评价工作。其他机构不得开展与创新型中小\\n企业、专精特新中小企业、专精特新“小巨人”企业有关的评\\n价、认定、授牌等活动。\\n第六条 各级中小企业主管部门应强化优质中小企业的动\\n3\\n态管理，建立健全“有进有出”的动态管理机制。“十四五”期\\n间，努力在全国推动培育一百万家创新型中小企业、十万家专\\n精特新中小企业、一万家专精特新“小巨人”企业。\\n第七条 工业和信息化部建设优质中小企业梯度培育平台\\n（https://zjtx.miit.gov.cn/，以下简称培育平台），搭建优质中小\\n企业数据库。各级中小企业主管部门应加强服务对接和监测分\\n析，对企业运行、发展态势、意见诉求，以及扶持政策与培育\\n成效等开展定期和不定期跟踪，有针对性地制定政策和开展精\\n准服务；进一步落实“放管服”要求，推动涉企数据互通共享，\\n减轻企业数据填报负担。\\n第二章 评价和认定\\n第八条 优质中小企业评价和认定工作坚持政策引领、企业\\n自愿、培育促进、公开透明的原则，按照“谁推荐、谁把关，\\n谁审核、谁管理”方式统筹开展、有序推进。\\n第九条 工业和信息化部发布并适时更新创新型中小企业\\n评价标准（附件1）、专精特新中小企业认定标准（附件2）和\\n专精特新“小巨人”企业认定标准（附件3）。专精特新中小企\\n业认定标准中的“特色化指标”，由省级中小企业主管部门结合\\n本地产业状况和中小企业发展实际设定并发布。\\n4\\n第十条 创新型中小企业评价，由企业按属地原则自愿登录\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 3, \"startOffset\": 1409, \"endOffset\": 2190, \"text\": \"业认定标准中的“特色化指标”，由省级中小企业主管部门结合\\n本地产业状况和中小企业发展实际设定并发布。\\n4\\n第十条 创新型中小企业评价，由企业按属地原则自愿登录\\n培育平台参与自评，省级中小企业主管部门根据评价标准，组\\n织对企业自评信息和相关佐证材料进行审核、实地抽查和公示。\\n公示无异议的，由省级中小企业主管部门公告为创新型中小企\\n业。\\n第十一条 专精特新中小企业认定，由创新型中小企业按属\\n地原则自愿提出申请，省级中小企业主管部门根据认定标准，\\n组织对企业申请材料和相关佐证材料进行审核、实地抽查和公\\n示。公示无异议的，由省级中小企业主管部门认定为专精特新\\n中小企业。\\n第十二条 专精特新“小巨人”企业认定，由专精特新中小\\n企业按属地原则自愿提出申请，省级中小企业主管部门根据认\\n定标准，对企业申请材料和相关佐证材料进行初审和实地抽查，\\n初审通过的向工业和信息化部推荐。工业和信息化部组织对被\\n推荐企业进行审核、抽查和公示。公示无异议的，由工业和信\\n息化部认定为专精特新“小巨人”企业。\\n原则上每年第二季度组织开展专精特新“小巨人”企业认\\n定工作，省级中小企业主管部门应根据工作要求，统筹做好创\\n新型中小企业评价、专精特新中小企业认定和专精特新“小巨\\n人”企业推荐工作。\\n5\\n第三章 动态管理\\n第十三条 经公告的创新型中小企业有效期为三年，每次到\\n期后由企业重新登录培育平台进行自评，经省级中小企业主管\\n部门审核（含实地抽查）通过后，有效期延长三年。经认定的\\n专精特新中小企业、专精特新“小巨人”企业有效期为三年，\\n每次到期后由认定部门组织复核（含实地抽查），复核通过的，\\n有效期延长三年。\\n第十四条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，应在每年4 月30 日前通过培育平\\n台更新企业信息。未及时更新企业信息的，取消复核资格。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 4, \"startOffset\": 2110, \"endOffset\": 2900, \"text\": \"有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，应在每年4 月30 日前通过培育平\\n台更新企业信息。未及时更新企业信息的，取消复核资格。\\n第十五条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，如发生更名、合并、重组、跨省\\n迁移、设立境外分支机构等与评价认定条件有关的重大变化，\\n应在发生变化后的3 个月内登录培育平台，填写重大变化情况\\n报告表。不再符合评价或认定标准的创新型中小企业和专精特\\n新中小企业，由省级中小企业主管部门核实后取消公告或认定；\\n不再符合认定标准的专精特新“小巨人”企业，由省级中小企\\n业主管部门核实后报工业和信息化部，由工业和信息化部取消\\n认定。对于未在3 个月内报告重大变化情况的，取消复核资格，\\n或直接取消公告或认定。\\n6\\n第十六条 有效期内的创新型中小企业、专精特新中小企业\\n和专精特新“小巨人”企业，如发生重大安全（含网络安全、\\n数据安全）、质量、环境污染等事故，或严重失信、偷漏税等违\\n法违规行为，或被发现存在数据造假等情形，直接取消公告或\\n认定，且至少三年内不得再次申报。\\n第十七条 任何组织和个人可针对创新型中小企业、专精特\\n新中小企业和专精特新“小巨人”企业相关信息真实性、准确\\n性等方面存在的问题，向相应中小企业主管部门实名举报，并\\n提供佐证材料和联系方式。对受理的举报内容，相应中小企业\\n主管部门应及时向被举报企业核实，被举报企业未按要求回复\\n或经核实确认该企业存在弄虚作假行为的，视情节轻重要求企\\n业进行整改，或直接取消公告或认定。\\n第四章 培育扶持\\n第十八条 中小企业主管部门应针对本地区不同发展阶段、\\n不同类型中小企业的特点和需求，建立优质中小企业梯度培育\\n体系，制定分层分类的专项扶持政策，加大服务力度，维护企\\n业合法权益，不断优化中小企业发展环境，激发涌现一大批专\\n精特新企业。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 5, \"startOffset\": 2820, \"endOffset\": 3591, \"text\": \"和需求，建立优质中小企业梯度培育\\n体系，制定分层分类的专项扶持政策，加大服务力度，维护企\\n业合法权益，不断优化中小企业发展环境，激发涌现一大批专\\n精特新企业。\\n第十九条 中小企业主管部门应发挥促进中小企业发展工\\n作协调机制作用，加强部门协同、上下联动，形成工作合力。\\n7\\n统筹运用财税、金融、技术、产业、人才、用地、用能等政策\\n工具持续支持优质中小企业发展，提高政策精准性和有效性。\\n第二十条 中小企业主管部门应着力构建政府公共服务、市\\n场化服务、公益性服务协同促进的服务体系，通过搭建创新成\\n果对接、大中小企业融通创新、创新创业大赛、供需对接等平\\n台，汇聚服务资源，创新服务方式，为中小企业提供全周期、\\n全方位、多层次的服务。通过普惠服务与精准服务相结合，着\\n力提升服务的广度、深度、精准度和响应速度，增强企业获得\\n感。\\n第二十一条 中小企业主管部门和各类中小企业服务机构\\n应加强指导和服务，促进中小企业提升公司治理、精细管理和\\n合规管理水平，防范各类风险，推动持续健康发展，切实发挥\\n优质中小企业示范作用。在评价、认定和服务过程中应注重对\\n企业商业秘密的保护，在宣传报道、考察交流前，应征得企业\\n同意。\\n第五章 附则\\n第二十二条 本办法由工业和信息化部负责解释。\\n第二十三条 本办法自2022 年8 月1 日起实施。8 月1 日前\\n已被省级中小企业主管部门认定的专精特新中小企业和已被工\\n业和信息化部认定的专精特新“小巨人”企业，继续有效。有\\n8\\n效期（最长不超过3 年）到期后自动失效，复核时按本办法执\\n行。\\n附件：1.创新型中小企业评价标准\\n2.专精特新中小企业认定标准\\n3.专精特新“小巨人”企业认定标准\\n4.部分指标和要求说明\\n9\\n附件1\\n创新型中小企业评价标准\\n一、公告条件\\n评价得分达到60 分以上（其中创新能力指标得分不低\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 6, \"startOffset\": 3511, \"endOffset\": 4306, \"text\": \".专精特新“小巨人”企业认定标准\\n4.部分指标和要求说明\\n9\\n附件1\\n创新型中小企业评价标准\\n一、公告条件\\n评价得分达到60 分以上（其中创新能力指标得分不低\\n于20 分、成长性指标及专业化指标得分均不低于15 分），\\n或满足下列条件之一：\\n（一）近三年内获得过国家级、省级科技奖励。\\n（二）获得高新技术企业、国家级技术创新示范企业、\\n知识产权优势企业和知识产权示范企业等荣誉（均为有效期\\n内）。\\n（三）拥有经认定的省部级以上研发机构。\\n（四）近三年新增股权融资总额（合格机构投资者的实\\n缴额）500万元以上。\\n二、评价指标\\n包括创新能力、成长性、专业化三类六个指标，评价结\\n果依分值计算，满分为100 分。\\n（一）创新能力指标（满分40分）\\n1.与企业主导产品相关的有效知识产权数量（满分20分）\\nA.Ⅰ类高价值知识产权1项以上（20分）\\nB. 自主研发的Ⅰ类知识产权1项以上（15分）\\nC.Ⅰ类知识产权1项以上（10分）\\n10\\nD.Ⅱ类知识产权1项以上（5分）\\nE. 无（0分）\\n2.上年度研发费用总额占营业收入总额比重（满分20分）\\nA.5%以上（20分）\\nB.3%-5%（15分）\\nC.2%-3%（10分）\\nD.1%-2%（5分）\\nE.1%以下（0分）\\n（二）成长性指标（满分30分）\\n3.上年度主营业务收入增长率（满分20分）\\nA.15%以上（20分）\\nB.10%-15%（15分）\\nC.5%-10%（10分）\\nD.0%-5%（5分）\\nE.0%以下（0分）\\n4.上年度资产负债率（满分10分）\\nA.55%以下（10分）\\nB.55%-75%（5分）\\nC.75%以上（0分）\\n（三）专业化指标（满分30分）\\n5.主导产品所属领域情况（满分10分）\\nA.属于《战略性新兴产业分类》（10分）\\n11\\nB.属于其他领域（5分）\\n6.上年度主营业务收入总额占营业收入总额比重（满分\\n20分）\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 7, \"startOffset\": 4226, \"endOffset\": 5015, \"text\": \"领域情况（满分10分）\\nA.属于《战略性新兴产业分类》（10分）\\n11\\nB.属于其他领域（5分）\\n6.上年度主营业务收入总额占营业收入总额比重（满分\\n20分）\\nA.70%以上（20分）\\nB.60%-70%（15分）\\nC.55%-60%（10分）\\nD.50%-55%（5分）\\nE.50%以下（0分）\\n12\\n附件2\\n专精特新中小企业认定标准\\n一、认定条件\\n同时满足以下四项条件即视为满足认定条件：\\n（一）从事特定细分市场时间达到2 年以上。\\n（二）上年度研发费用总额不低于100 万元，且占营业\\n收入总额比重不低于3%。\\n（三）上年度营业收入总额在1000 万元以上，或上年\\n度营业收入总额在1000 万元以下，但近2 年新增股权融资\\n总额（合格机构投资者的实缴额）达到2000 万元以上。\\n（四）评价得分达到60 分以上或满足下列条件之一：\\n1.近三年获得过省级科技奖励，并在获奖单位中排名前\\n三；或获得国家级科技奖励，并在获奖单位中排名前五。\\n2.近两年研发费用总额均值在1000万元以上。\\n3.近两年新增股权融资总额（合格机构投资者的实缴额）\\n6000万元以上。\\n4.近三年进入“创客中国”中小企业创新创业大赛全国\\n500强企业组名单。\\n二、评价指标\\n包括专业化、精细化、特色化和创新能力四类十三个指\\n标，评价结果依分值计算，满分为100 分。\\n13\\n（一）专业化指标（满分 25 分）\\n1.上年度主营业务收入总额占营业收入总额比重（满分\\n5 分）\\nA.80%以上（5 分）\\nB.70%-80%（3 分）\\nC.60%-70%（1 分）\\nD.60%以下（0 分）\\n2.近 2 年主营业务收入平均增长率（满分 10 分）\\nA.10%以上（10 分）\\nB.8%-10%（8 分）\\nC.6%-8%（6 分）\\nD.4%-6%（4 分）\\nE.0%-4%（2 分）\\nF.0%以下（0 分）\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 8, \"startOffset\": 4935, \"endOffset\": 5731, \"text\": \"A.10%以上（10 分）\\nB.8%-10%（8 分）\\nC.6%-8%（6 分）\\nD.4%-6%（4 分）\\nE.0%-4%（2 分）\\nF.0%以下（0 分）\\n3.从事特定细分市场年限（满分 5 分）\\n每满2 年得1 分，最高不超过5 分。\\n4.主导产品所属领域情况（满分 5 分）\\nA. 在产业链供应链关键环节及关键领域“补短板”“锻\\n长板”“填空白”取得实际成效（5 分）\\nB. 属于工业“六基”领域、中华老字号名录或企业主导\\n产品服务关键产业链重点龙头企业（3 分）\\nC. 不属于以上情况（0 分）\\n14\\n（二）精细化指标（满分 25 分）\\n5.数字化水平（满分 5 分）\\nA. 三级以上（5 分）\\nB. 二级（3 分）\\nC. 一级（0 分）\\n6.质量管理水平（每满足一项加 3 分，最高不超过 5 分）\\nA. 获得省级以上质量奖荣誉\\nB. 建立质量管理体系，获得ISO9001 等质量管理体系\\n认证证书\\nC. 拥有自主品牌\\nD. 参与制修订标准\\n7.上年度净利润率（满分 10 分）\\nA.10%以上（10 分）\\nB.8%-10%（8 分）\\nC.6%-8%（6 分）\\nD.4%-6%（4 分）\\nE.2%-4%（2 分）\\nF.2%以下（0 分）\\n8.上年度资产负债率（满分 5 分）\\nA.50%以下（5 分）\\nB.50%-60%（3 分）\\nC.60%-70%（1 分）\\n15\\nD.70%以上（0 分）\\n（三）特色化指标（满分 15 分）\\n9.地方特色指标。由省级中小企业主管部门结合本地产\\n业状况和中小企业发展实际自主设定 1-3 个指标进行评价\\n（满分 15 分）\\n（四）创新能力指标（满分 35 分）\\n10.与企业主导产品相关的有效知识产权数量（满分 10\\n分）\\nA.Ⅰ类高价值知识产权1项以上（10分）\\nB. 自主研发Ⅰ类知识产权1项以上（8分）\\nC.Ⅰ类知识产权1项以上（6分）\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 9, \"startOffset\": 5651, \"endOffset\": 6436, \"text\": \"关的有效知识产权数量（满分 10\\n分）\\nA.Ⅰ类高价值知识产权1项以上（10分）\\nB. 自主研发Ⅰ类知识产权1项以上（8分）\\nC.Ⅰ类知识产权1项以上（6分）\\nD.Ⅱ类知识产权1项以上（2分）\\nE. 无（0分）\\n11.上年度研发费用投入（满分 10 分）\\nA. 研发费用总额500 万元以上或研发费用总额占营业\\n收入总额比重在10%以上（10 分）\\nB. 研发费用总额 400-500 万元或研发费用总额占营业\\n收入总额比重在8%-10%（8 分）\\nC. 研发费用总额 300-400 万元或研发费用总额占营业\\n收入总额比重在6%-8%（6 分）\\nD. 研发费用总额 200-300 万元或研发费用总额占营业\\n收入总额比重在4%-6%（4 分）\\n16\\nE. 研发费用总额100-200 万元或研发费用总额占营业收\\n入总额比重在3%-4%（2 分）\\nF. 不属于以上情况（0 分）\\n12.上年度研发人员占比（满分 5 分）\\nA.20%以上（5 分）\\nB.10%-20%（3 分）\\nC.5%-10%（1 分）\\nD.5%以下（0 分）\\n13.建立研发机构级别（满分 10 分）\\nA. 国家级（10 分）\\nB. 省级（8 分）\\nC. 市级（4 分）\\nD. 市级以下（2 分）\\nE. 未建立研发机构（0 分）\\n17\\n附件3\\n专精特新“小巨人”企业认定标准\\n专精特新“小巨人”企业认定需同时满足专、精、特、\\n新、链、品六个方面指标。\\n一、专业化指标\\n坚持专业化发展道路，长期专注并深耕于产业链某一环\\n节或某一产品。截至上年末，企业从事特定细分市场时间达\\n到3 年以上，主营业务收入总额占营业收入总额比重不低于\\n70%，近2 年主营业务收入平均增长率不低于5%。\\n二、精细化指标\\n重视并实施长期发展战略，公司治理规范、信誉良好、\\n社会责任感强，生产技术、工艺及产品质量性能国内领先，\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 10, \"startOffset\": 6356, \"endOffset\": 7149, \"text\": \"年主营业务收入平均增长率不低于5%。\\n二、精细化指标\\n重视并实施长期发展战略，公司治理规范、信誉良好、\\n社会责任感强，生产技术、工艺及产品质量性能国内领先，\\n注重数字化、绿色化发展，在研发设计、生产制造、供应链\\n管理等环节，至少1 项核心业务采用信息系统支撑。取得相\\n关管理体系认证，或产品通过发达国家和地区产品认证（国\\n际标准协会行业认证）。截至上年末，企业资产负债率不高\\n于70%。\\n三、特色化指标\\n技术和产品有自身独特优势，主导产品在全国细分市场\\n占有率达到10%以上，且享有较高知名度和影响力。拥有直\\n接面向市场并具有竞争优势的自主品牌。\\n四、创新能力指标\\n18\\n满足一般性条件或创新直通条件。\\n（一）一般性条件。需同时满足以下三项：\\n1.上年度营业收入总额在1 亿元以上的企业，近2 年研\\n发费用总额占营业收入总额比重均不低于3%；上年度营业\\n收入总额在5000 万元—1 亿元的企业，近2 年研发费用总额\\n占营业收入总额比重均不低于6%；上年度营业收入总额在\\n5000 万元以下的企业，同时满足近2 年新增股权融资总额（合\\n格机构投资者的实缴额）8000 万元以上，且研发费用总额\\n3000 万元以上、研发人员占企业职工总数比重50%以上。\\n2.自建或与高等院校、科研机构联合建立研发机构，设\\n立技术研究院、企业技术中心、企业工程中心、院士专家工\\n作站、博士后工作站等。\\n3.拥有2 项以上与主导产品相关的Ⅰ类知识产权，且实际\\n应用并已产生经济效益。\\n（二）创新直通条件。满足以下一项即可：\\n1.近三年获得国家级科技奖励，并在获奖单位中排名前\\n三。\\n2.近三年进入“创客中国”中小企业创新创业大赛全国\\n50 强企业组名单。\\n五、产业链配套指标\\n位于产业链关键环节，围绕重点产业链实现关键基础技\\n术和产品的产业化应用，发挥“补短板”“锻长板”“填空白”\\n19\\n等重要作用。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 11, \"startOffset\": 7069, \"endOffset\": 7847, \"text\": \"业组名单。\\n五、产业链配套指标\\n位于产业链关键环节，围绕重点产业链实现关键基础技\\n术和产品的产业化应用，发挥“补短板”“锻长板”“填空白”\\n19\\n等重要作用。\\n六、主导产品所属领域指标\\n主导产品原则上属于以下重点领域：从事细分产品市场\\n属于制造业核心基础零部件、元器件、关键软件、先进基础\\n工艺、关键基础材料和产业技术基础；或符合制造强国战略\\n十大重点产业领域；或属于网络强国建设的信息基础设施、\\n关键核心技术、网络安全、数据安全领域等产品。\\n20\\n附件4\\n部分指标和要求说明\\n（一）指标中如对期限无特殊说明，一般使用企业近1 年\\n的年度数据，具体定义为：指企业上一完整会计年度，以企业\\n上一年度审计报告期末数为准。对于存在子公司或母公司的企\\n业，按财政部印发的《企业会计准则》有关规定执行。\\n（二）所称拥有自主品牌是指主营业务产品或服务具有自\\n主知识产权，且符合下列条件之一：\\n1.产品或服务品牌已经国家知识产权局商标局正式注册。\\n2.产品或服务已经实现收入。\\n（三）所称“Ⅰ类知识产权”包括发明专利（含国防专利）、\\n植物新品种、国家级农作物品种、国家新药、国家一级中药保\\n护品种、集成电路布图设计专有权（均不包含转让未满1 年的\\n知识产权）。\\n（四）所称“Ⅰ类高价值知识产权”须符合以下条件之一：\\n1.在海外有同族专利权的发明专利或在海外取得收入的其\\n他Ⅰ类知识产权，其中专利限G20 成员、新加坡以及欧洲专利\\n局经实质审查后获得授权的发明专利。\\n2.维持年限超过10 年的Ⅰ类知识产权。\\n3.实现较高质押融资金额的Ⅰ类知识产权。\\n21\\n4.获得国家科学技术奖或中国专利奖的Ⅰ类知识产权。\\n（五）所称“Ⅱ类知识产权”包括与主导产品相关的软件\\n著作权（不含商标）、授权后维持超过2 年的实用新型专利或外\\n观设计专利（均不包含转让未满1 年的知识产权）。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 12, \"startOffset\": 7767, \"endOffset\": 8555, \"text\": \"五）所称“Ⅱ类知识产权”包括与主导产品相关的软件\\n著作权（不含商标）、授权后维持超过2 年的实用新型专利或外\\n观设计专利（均不包含转让未满1 年的知识产权）。\\n（六）所称“企业数字化转型水平”是指在优质中小企业\\n梯度培育平台完成数字化水平免费自测，具体自测网址、相关\\n标准等事宜，另行明确。\\n（七）所称“重大安全（含网络安全、数据安全）、质量、\\n环境污染等事故”是指产品安全、生产安全、工程质量安全、\\n环境保护、网络安全等各级监管部门，依据《中华人民共和国\\n安全生产法》《中华人民共和国环境保护法》《生产安全事故报\\n告和调查处理条例》《中华人民共和国网络安全法》《中华人民\\n共和国数据安全法》等法律法规，最高人民法院、最高人民检\\n察院司法解释，部门规章以及地方法规等出具的判定意见。\\n（八）所称“股权融资”是指公司股东稀释部分公司股权\\n给投资人，以增资扩股（出让股权不超过30%）的方式引进新\\n的股东，从而取得公司融资的方式。\\n（九）所称“合格机构投资者”是指符合《创业投资企业\\n管理暂行办法》（发展改革委等10 部门令第39 号）或者《私募\\n投资基金监督管理暂行办法》（证监会令第105 号）相关规定，\\n按照上述规定完成备案且规范运作的创业投资基金及私募股权\\n22\\n投资基金。\\n（十）所称“主导产品”是指企业核心技术在产品中发挥\\n重要作用，且产品收入之和占企业同期营业收入比重超过50%。\\n（十一）所称“主导产品在全国细分市场占有率达到10%\\n以上，且享有较高知名度和影响力”可通过企业自证或其他方\\n式佐证。\\n（十二）所称“省级科技奖励”包括各省、自治区、直辖\\n市科学技术奖的一、二、三等奖；“国家级科技奖励”包括国家\\n科学技术进步奖、国家自然科学奖、国家技术发明奖，以及国\\n防科技奖。\\n（十三）如无特殊说明，所称“以上”、“以下”，包括本数；\\n所称的“超过”，不包括本数。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}, {\"ordinal\": 13, \"startOffset\": 8475, \"endOffset\": 8939, \"text\": \"国家\\n科学技术进步奖、国家自然科学奖、国家技术发明奖，以及国\\n防科技奖。\\n（十三）如无特殊说明，所称“以上”、“以下”，包括本数；\\n所称的“超过”，不包括本数。在计算评价指标得分时，如指标\\n值位于两个评分区间边界上，按高分计算得分。\\n（十四）本办法部分指标计算公式\\n近2 年主营业务收入平均增长率=（企业上一年度主营业务\\n收入增长率+企业上上年度主营业务收入增长率）/2。\\n企业上一年度主营业务收入增长率=（企业上一年度主营业\\n务收入总额-企业上上年度主营业务收入总额）/企业上上年度主\\n营业务收入总额*100%。其他年度主营业务收入增长率计算方\\n法以此类推。\\n（十五）所称“被列入经营异常名录”以国家企业信用信\\n23\\n息公示系统（http://www.gsxt.gov.cn）查询结果为准；所称“严\\n重失信主体名单”以信用中国（http://www.creditchina.gov.cn）\\n查询结果为准。\\n（十六）所称“创客中国”中小企业创新创业大赛全国500\\n强、50 强企业组名单是指该大赛2021 年以来正式发布的名单。\", \"pageNumber\": null, \"aiReviewStatus\": \"PASS\", \"aiReviewMessage\": \"默认语义切片：800/80\", \"manualEdited\": false, \"version\": 0}], \"chunking\": {\"category\": \"FINANCE_POLICY\", \"strategy\": \"SEMANTIC\", \"chunkSize\": 800, \"overlap\": 80, \"delimiterRegex\": null}, \"pages\": []}',NULL,'PASS','2026-09-20 15:54:34','/files/finance-policy/工业和信息化部关于印发《优质中小企业梯度培育管理暂行办法》的通知.pdf'),('28a3778d-951e-5f1d-8f9e-07a49dce9c3e',1,'{\"report\": {\"id\": \"28a3778d-951e-5f1d-8f9e-07a49dce9c3e\", \"createdAt\": \"2026-09-20T15:54:33\", \"metadata\": {\"title\": \"延安市人民政府办公室 br 关于印发《延安市进一步促进民营经济高质量发展“十大行动”实施方案》的通知--市工业和信息化局1788427813000\", \"documentNo\": \"\", \"issuer\": \"延安市人民政府\", \"sourceUrl\": \"/files/finance-policy/延安市人民政府办公室_br__关于印发《延安市进一步促进民营经济高质量发展“十大行动”实施方案》的通知--市工业和信息化局1788427813000.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"textHash\": \"77e61295c0538b8e715534b6a50189dbb7aac71c3863e638d8be213a3a194348\", \"decision\": \"PASS\", \"score\": 100, \"scores\": {\"ENCODING\": 100, \"AUTHENTICITY\": 100, \"FORMAT\": 100, \"QUALITY\": 100}, \"issues\": [], \"evidence\": {\"officialMetadata\": {\"title\": \"延安市人民政府办公室 br 关于印发《延安市进一步促进民营经济高质量发展“十大行动”实施方案》的通知--市工业和信息化局1788427813000\", \"documentNo\": \"\", \"issuer\": \"延安市人民政府\", \"sourceUrl\": \"/files/finance-policy/延安市人民政府办公室_br__关于印发《延安市进一步促进民营经济高质量发展“十大行动”实施方案》的通知--市工业和信息化局1788427813000.pdf\", \"kind\": \"POLICY\", \"validity\": \"UNKNOWN\", \"effectiveDate\": null, \"expiryDate\": null, \"historical\": false}, \"officialTextHash\": \"77e61295c0538b8e715534b6a50189dbb7aac71c3863e638d8be213a3a194348\", \"validitySourceUrl\": \"/files/finance-policy/延安市人民政府办公室_br__关于印发《延安市进一步促进民营经济高质量发展“十大行动”实施方案》的通知--市工业和信息化局1788427813000.pdf\", \"note\": \"批量导入：已审核通过并加入金融政策库。\", \"revie