DROP TABLE IF EXISTS `cms_expert_profile`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_expert_profile` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `tenant_id` bigint NOT NULL,
  `user_id` bigint NOT NULL COMMENT 'BASE/System 用户编号',
  `expert_name` varchar(64) NOT NULL,
  `professional_title` varchar(64) DEFAULT NULL,
  `company` varchar(128) DEFAULT NULL,
  `service_fields` varchar(1000) NOT NULL,
  `introduction` text,
  `fixed_price` int NOT NULL COMMENT '固定文字咨询价格，分',
  `audit_status` tinyint NOT NULL DEFAULT '0' COMMENT '0待审核 1通过 2驳回',
  `audit_remark` varchar(500) DEFAULT NULL,
  `enabled` bit(1) NOT NULL DEFAULT b'0',
  `rating` decimal(3,2) NOT NULL DEFAULT '0.00',
  `order_count` int NOT NULL DEFAULT '0',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_cms_expert_user` (`tenant_id`,`user_id`,`deleted`),
  KEY `idx_cms_expert_audit` (`tenant_id`,`audit_status`,`enabled`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='CMS专家资料';
