DROP TABLE IF EXISTS `cms_finance_policy_ext`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_finance_policy_ext` (
  `tenant_id` bigint NOT NULL COMMENT '租户编号',
  `review_id` varchar(36) NOT NULL COMMENT '关联知识文档审查编号',
  `applicable_regions` json DEFAULT NULL COMMENT '适用地区数组',
  `applicable_industries` json DEFAULT NULL COMMENT '适用行业数组',
  `applicable_enterprise_types` json DEFAULT NULL COMMENT '适用企业类型数组',
  `support_type` varchar(64) DEFAULT NULL COMMENT '支持方式',
  `amount_min` decimal(15,2) DEFAULT NULL COMMENT '最低金额',
  `amount_max` decimal(15,2) DEFAULT NULL COMMENT '最高金额',
  `amount_unit` varchar(16) NOT NULL DEFAULT '万元' COMMENT '金额单位',
  `support_rate` decimal(5,2) DEFAULT NULL COMMENT '支持比例（%）',
  `support_description` text COMMENT '原始金额描述',
  `apply_start_time` datetime DEFAULT NULL COMMENT '申报开始时间',
  `apply_end_time` datetime DEFAULT NULL COMMENT '申报截止时间',
  `policy_status` tinyint NOT NULL DEFAULT '1' COMMENT '1现行 2即将截止 3已废止',
  `interpretation_status` varchar(24) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/REVIEWING/APPROVED/REJECTED',
  `interpretation_json` json DEFAULT NULL COMMENT '经过后端校验的AI结构化解读',
  `creator` varchar(64) NOT NULL DEFAULT '',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) NOT NULL DEFAULT '',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0',
  `version` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`tenant_id`,`review_id`),
  KEY `idx_finance_policy_deadline` (`tenant_id`,`policy_status`,`apply_end_time`),
  CONSTRAINT `fk_finance_policy_document` FOREIGN KEY (`tenant_id`, `review_id`) REFERENCES `cms_knowledge_document` (`tenant_id`, `review_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业金融政策结构化扩展';
/*!40101 SET character_set_client = @saved_cs_client */;

