--
-- Table structure for table `cms_knowledge_chunk`
--

DROP TABLE IF EXISTS `cms_knowledge_chunk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_knowledge_chunk` (
  `review_id` varchar(36) NOT NULL,
  `tenant_id` bigint NOT NULL,
  `ordinal` int NOT NULL,
  `start_offset` int NOT NULL,
  `end_offset` int NOT NULL,
  `content` text NOT NULL,
  `es_index_name` varchar(64) DEFAULT NULL COMMENT '实际写入的ES索引',
  `page_number` int DEFAULT NULL COMMENT '对应PDF页码',
  `ai_review_result` varchar(32) NOT NULL DEFAULT 'PASS' COMMENT 'PASS/WARN/FAIL',
  `ai_review_message` varchar(1000) DEFAULT NULL COMMENT '切片质检说明',
  `is_manual_edited` tinyint(1) NOT NULL DEFAULT '0' COMMENT '是否人工修改',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '切片乐观锁版本',
  `valid` tinyint(1) NOT NULL DEFAULT '1' COMMENT '部分驳回时是否有效',
  PRIMARY KEY (`tenant_id`,`review_id`,`ordinal`),
  CONSTRAINT `fk_cms_chunk_document` FOREIGN KEY (`tenant_id`, `review_id`) REFERENCES `cms_knowledge_document` (`tenant_id`, `review_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

