--
-- Table structure for table `cms_knowledge_document`
--

DROP TABLE IF EXISTS `cms_knowledge_document`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `cms_knowledge_document` (
  `review_id` varchar(36) NOT NULL,
  `tenant_id` bigint NOT NULL,
  `title` varchar(300) NOT NULL,
  `validity` varchar(32) NOT NULL,
  `source_url` varchar(2000) NOT NULL,
  `text_hash` char(64) NOT NULL,
  `content` longtext NOT NULL,
  `published` bit(1) NOT NULL DEFAULT b'0' COMMENT '审查通过后仅入库，由管理员发布后才可检索',
  `deleted_at` datetime DEFAULT NULL COMMENT '管理员下架时间，审查记录仍保留',
  `created_at` datetime NOT NULL,
  `doc_category` varchar(32) NOT NULL DEFAULT 'LAW' COMMENT 'QA:智能问答库, LAW:标准法规库',
  `local_pdf_path` varchar(500) DEFAULT NULL COMMENT 'MinIO或文件服务中的本地原件/快照路径',
  `chunk_strategy` varchar(64) NOT NULL DEFAULT 'REGEX' COMMENT '切片策略',
  `chunk_config` json DEFAULT NULL COMMENT '切片参数',
  `review_status` varchar(32) NOT NULL DEFAULT 'PENDING_MANUAL_REVIEW' COMMENT '生命周期状态',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '文档乐观锁版本',
  PRIMARY KEY (`tenant_id`,`review_id`),
  KEY `idx_cms_document_lifecycle` (`tenant_id`,`doc_category`,`review_status`,`deleted_at`),
  CONSTRAINT `fk_cms_knowledge_review` FOREIGN KEY (`tenant_id`, `review_id`) REFERENCES `cms_document_review` (`tenant_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

