INSERT INTO `cms_policy` VALUES (1,'金融政策','住房和城乡建设部关于推动绿色建材应用提升建筑品质的通知',1,'中华人民共和国住房和城乡建设部','建筑节能','现行有效','2026-06-15',NULL,'2026-07-01','<p>为落实碳达峰碳中和目标，现就推动绿色建材在建筑工程中的应用提出以下意见：一、提高绿色建材在城镇新建建筑中的应用比例……二、加强保温隔热材料燃烧性能与导热系数抽检……</p>','<p>为落实碳达峰碳中和目标，现就推动绿色建材在建筑工程中的应用提出以下意见：一、提高绿色建材在城镇新建建筑中的应用比例……二、加强保温隔热材料燃烧性能与导热系数抽检……</p>','https://www.mohurd.gov.cn/gongkai/zhengce/zhengcefilelib/index.html','住房和城乡建设部官网',NULL,156,0,0,1,NULL,1,'2026-09-03 14:59:48',1,'2026-09-03 14:59:48',NULL,'2026-09-07 15:27:31',0,1),(2,'金融政策','关于加强城镇供热管网安全运行管理的指导意见',1,'中华人民共和国住房和城乡建设部','供热安全','现行有效','2026-04-20',NULL,'2026-05-10','<p>各地要加快老旧供热管网更新改造，直埋供热管道应按GB/T 29047要求进行保温层与外护管质量验收，建立健全泄漏监测台账……</p>','<p>各地要加快老旧供热管网更新改造，直埋供热管道应按GB/T 29047要求进行保温层与外护管质量验收，建立健全泄漏监测台账……</p>','https://www.mohurd.gov.cn/gongkai/zhengce/zhengcefilelib/index.html','住房和城乡建设部官网',NULL,98,0,0,1,NULL,1,'2026-09-03 14:59:48',1,'2026-09-03 14:59:48',NULL,'2026-09-07 15:27:31',0,1),(3,'金融政策','陕西省促进绿色低碳建材产业发展若干措施',2,'陕西省住房和城乡建设厅','产业政策','现行有效','2026-03-08',NULL,'2026-04-01','<p>对获得绿色建材认证的保温、防腐产品，在政府采购、工程招标中给予加分支持；鼓励企业开展产品碳足迹核算……</p>','<p>对获得绿色建材认证的保温、防腐产品，在政府采购、工程招标中给予加分支持；鼓励企业开展产品碳足迹核算……</p>','https://zjt.shaanxi.gov.cn/','陕西省住房和城乡建设厅官网',NULL,67,0,0,1,NULL,1,'2026-09-03 14:59:48',1,'2026-09-03 14:59:48',NULL,'2026-09-07 15:27:31',0,1),(4,'金融政策','Policy news test',1,NULL,NULL,'现行有效','2026-01-01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,3,NULL,0,NULL,1,'2026-09-03 11:48:55',1,'2026-09-03 11:48:55',0,1),(5,'金融政策','Policy news test',1,NULL,NULL,'现行有效','2026-01-01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,3,NULL,0,NULL,1,'2026-09-03 11:50:47',1,'2026-09-03 11:50:47',0,1),(6,'金融政策','Policy news test',1,NULL,NULL,'现行有效','2026-01-01',NULL,NULL,NULL,NULL,NULL,NULL,NULL,0,0,0,0,'',0,NULL,1,'2026-09-03 11:59:07',1,'2026-09-07 01:39:29',0,1),(7,'金融政策','首次认定高企奖励10万元；重新认定高企奖励2.5万元',3,'科技局','财政奖励','现行有效',NULL,NULL,NULL,'【适用企业】高新技术企业\n【政策核心内容】首次认定高企奖励10万元；重新认定高企奖励2.5万元\n【政策依据】延安市本地政策\n【文件文号】延政办发〔2025〕23号《延安市进一步促进民营经济高质量发展“十大行动”实施方案》[(延安市人民...)]\n【申报主管部门】科技局\n\n','【适用企业】高新技术企业 【政策核心内容】首次认定高企奖励10万元；重新认定高企奖励2.5万元 【政策依据】延安市本地政策 【文件文号】延政办发〔2025〕23号《延安市进一步促进民营经济高质量发展“十大行动”实施方案》[(延安市人民...)] 【申报主管部门】科技局',NULL,'延安市本地政策','[\"/files/policy/p7.pdf\"]',0,0,0,1,NULL,1,'2026-09-07 10:11:55',1,'2026-09-07 10:11:55',NULL,'2026-09-07 17:17:00',0,1),(8,'金融政策','企业所得税减按15%征收（一般企业25%）',1,'税务局','税收优惠','现行有效',NULL,NULL,NULL,'【适用企业】高新技术企业\n【政策核心内容】企业所得税减按15%征收（一般企业25%）\n【政策依据】国家长期有效政策\n【文件文号】国科发火〔2016〕32号《高新技术企业认定管理办法》\n【申报主管部门】税务局','【适用企业】高新技术企业 【政策核心内容】企业所得税减按15%征收（一般企业25%） 【政策依据】国家长期有效政策 【文件文号】国科发火〔2016〕32号《高新技术企业认定管理办法》 【申报主管部门】税务局',NULL,'国家长期有效政策','[\"/files/policy/p8.pdf\"]',0,0,0,1,NULL,1,'2026-09-07 10:11:55',1,'2026-09-07 10:11:55',NULL,'2026-09-07 15:27:31',0,1),(9,'金融政策','研发费用100%加计扣除',1,'税务局','税收优惠','现行有效',NULL,NULL,NULL,'【适用企业】高新技术企业\n【政策核心内容】研发费用100%加计扣除\n【政策依据】国家长期有效政策\n【文件文号】财政部 税务总局公告2023年第7号\n【申报主管部门】税务局\n\n【政策文件全文】\n来源文件：财政部 税务总局关于进一步完善研发费用税前加计扣除政策的公告.pdf\n财政部 税务总局关于进一步完善研发费用税前加计\n扣除政策的公告 \n财政部 税务总局公告 2023 年第 7 号 \n为进一步激励企业加大研发投入，更好地支持科技创新，现就企\n业研发费用税前加计扣除政策有关问题公告如下：\n一、企业开展研发活动中实际发生的研发费用，未形成无形资产\n计入当期损益的，在按规定据实扣除的基础上，自 2023 年 1 月 1 日\n起，再按照实际发生额的100%在税前加计扣除；形成无形资产的，自\n2023 年 1 月 1 日起，按照无形资产成本的 200%在税前摊销。\n二、企业享受研发费用加计扣除政策的其他政策口径和管理要求，\n按照《财政部 国家税务总局 科技部关于完善研究开发费用税前加计\n扣除政策的通知》（财税〔2015〕119 号）、《财政部 税务总局 科\n技部关于企业委托境外研究开发费用税前加计扣除有关政策问题的通\n知》（财税〔2018〕64 号）等文件相关规定执行。\n三、本公告自 2023 年 1 月 1 日起执行，《财政部 税务总局关于\n进一步完善研发费用税前加计扣除政策的公告》（财政部 税务总局公\n告 2021 年第 13 号）、《财政部 税务总局 科技部关于进一步提高科\n技型中小企业研发费用税前加计扣除比例的公告》（财政部 税务总局\n科技部公告 2022 年第 16 号）、《财政部 税务总局 科技部关于加大\n支持科技创新税前扣除力度的公告》（财政部 税务总局 科技部公告\n2022 年第 28 号）同时废止。\n特此公告。\n财政部 税务总局\n2023 年 3 月 26 日','【适用企业】高新技术企业 【政策核心内容】研发费用100%加计扣除 【政策依据】国家长期有效政策 【文件文号】财政部 税务总局公告2023年第7号 【申报主管部门】税务局 【政策文件全文】 来源文件：财政部 税务总局关于进一步完善研发费用税前加计扣除政策的公告.pdf 财政部 税务总局关于进一步完善研发费用税前加计 扣除政策的公告 财政部 税务总局公告 2023 年第 7 号 为进一步激励企',NULL,'国家长期有效政策','[\"/files/policy/p9.pdf\"]',0,0,0,1,NULL,1,'2026-09-07 10:11:55',1,'2026-09-07 10:11:55',NULL,'2026-09-07 15:27:31',0,1),(10,'金融政策','亏损结转年限延长至10年',1,'税务局','税收优惠','现行有效',NULL,NUL